function tkCard(e,i){const d=new Date(e.date+'T12:00:00'),day=String(d.getDate()).padStart(2,'0'),mon=d.toLocaleDateString('en-GB',{month:'short'}).toUpperCase(),dow=d.toLocaleDateString('en-GB',{weekday:'short'}),left=Math.ceil((d-new Date())/864e5),soon=left<0?'':left===0?'Tonight':left===1?'Tomorrow':`In ${left} days`;return `<article class="tk-card tk-lite tone-${tkTone[e.color]||'blue'}" data-i="${i}" aria-label="${esc(e.title)}"><div class="tk-tilt"><div class="tk-face"><div class="tk-art"><img src="${esc(posterImage(e))}" alt="" ${i===0?'fetchpriority="high"':'loading="lazy"'}></div><i class="tk-scrim"></i><i class="tk-stub"></i><i class="tk-holo"></i><i class="tk-glare"></i></div><span class="tk-dpill"><b>${day}</b>${mon}</span><span class="tk-chip">${esc(layoutOf(e).label)}</span><div class="tk-body"><div class="tk-row1"><span class="tk-artist">${esc(e.artist)}</span>${soon?`<em>${soon}</em>`:''}</div><h3 class="tk-title">${esc(e.title)}</h3><p class="tk-when">${esc(dow)}, ${esc(date(e.date))} · ${esc(e.time)} ${tzOf(e)}</p><p class="tk-where">${esc(e.venue)}, ${esc(e.city)}</p><div class="tk-foot"><span>From <b>${money(e.price)}</b></span><a class="tk-cta" href="#/event/${esc(e.slug)}">View tickets</a></div></div></div></article>`}
