const seatZones=[{name:'CAT 2 · Back',key:'back',add:0,rows:['A','B']},{name:'CAT 1 · Left / Right',key:'side',add:9,rows:['C','D']},{name:'VIP · Front',key:'front',add:19,rows:['E','F']}];

