const layoutOf=e=>VENUES[e?.layout]||VENUES.arena;
const zonesOf=e=>layoutOf(e).zones;
const zoneOf=(e,id)=>zonesOf(e).find(z=>z.id===id);
const zonePrice=(e,z)=>e.price+z.add;
const hash=str=>[...str].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,7);
const zoneSold=(e,z)=>{const h=hash(e.id+':'+z.id);const seeded=h%17===0?z.cap:Math.floor(z.cap*((h%70)/100));return Math.min(z.cap,seeded+tickets.filter(t=>t.eventId===e.id&&t.zone===z.id).length)};
const zoneLeft=(e,z)=>{const base=Math.max(0,z.cap-zoneSold(e,z));if(e.id in demoStock){const cheapest=zonesOf(e).reduce((m,x)=>x.add<m.add?x:m);return z.id===cheapest.id?Math.min(base,demoStock[e.id]):0}return base};
const venueLeft=e=>zonesOf(e).reduce((n,z)=>n+zoneLeft(e,z),0);
const venueCap=e=>zonesOf(e).reduce((n,z)=>n+z.cap,0);
const ownerKey=()=>wallet||(user?'demo:'+user.email:'');
const ownedCount=e=>{const k=ownerKey().toLowerCase();return k?tickets.filter(t=>t.eventId===e.id&&(t.owner||'').toLowerCase()===k).length:0};
const limitLeft=e=>Math.max(0,MAX_PER-ownedCount(e));
const orderItems=e=>order?.eventId===e?.id?(order.items||[order]):[];
const zoneQty=(e,id)=>orderItems(e).filter(i=>i.zone===id).length;
let activeZone=null;
function setOrder(e,items){if(!items.length){order=null;return}const total=items.reduce((n,i)=>n+i.price,0),same=items.every(i=>i.zone===items[0].zone);order={eventId:e.id,items,qty:items.length,price:total,tier:same?items[0].tier:items.length+' tickets',tierIndex:items[0].tierIndex||0}}
function setZoneQty(e,id,n){const z=zoneOf(e,id);if(!z)return;const others=orderItems(e).filter(i=>i.zone!==id);const room=Math.min(limitLeft(e)-others.length,zoneLeft(e,z));const want=Math.max(0,Math.min(room,n));if(n>want)toast(room<=0&&limitLeft(e)-others.length<=0?`You can hold up to ${MAX_PER} tickets for this concert.`:`Only ${zoneLeft(e,z)} left in ${z.name}.`);const idx=zonesOf(e).findIndex(x=>x.id===id);setOrder(e,[...others,...Array.from({length:want},()=>({zone:id,tier:z.name,tierIndex:idx,price:zonePrice(e,z)}))]);paid=false;refreshSelector(e)}
// ---- maps: one per venue type ----
