const tours={global:[['nav','Everything starts here.','Explore concerts, check your tickets, or open your profile.'],['discover','Find your next concert.','Browse upcoming concerts and filter by artist, venue, or ticket type.'],['tickets','Your tickets live here.','Find your ticket details and any on-chain verification in My Tickets.'],['wallet','Connect when you’re ready.','Approve a connection in MetaMask. Ticketrue never asks for your Secret Recovery Phrase.'],['chain','Ownership you can check.','BOT Chain records ownership when a configured contract transaction is confirmed. Demo tickets are clearly marked.'],['discover','You’re ready.','Pick a concert. We’ll guide you through the rest.']],event:[['event','Meet the show.','Check the artist, date, venue, and opening time.'],['selector','Find your spot.','Pick a section and up to four seats, or a ticket tier and how many.'],['availability','Check availability.','Unavailable seats cannot be selected. Final inventory is checked again at issuance.'],['ownership','Up to four each.','One person can hold up to four tickets for each concert.']],seat:[['selector','The stage is at the top.','Inspect rows A–F. Blue seats are available; dark seats are unavailable.'],['selector','Choose your seat.','Tap a blue seat. Your selection turns yellow and the price updates.'],['selector','Ready for checkout.','Only one seat can be selected. Continue when your seat looks right.']],tier:[['selector','Pick your experience.','Compare viewing areas, entry benefits, and prices.'],['availability','Availability matters.','Each tier has limited inventory. One person can hold up to four tickets per concert.'],['selector','Continue when ready.','Select a tier and review the total before checkout.']],checkout:[['summary','Your order, at a glance.','Confirm your concert, date, seat or tier, and total.'],['payment','Indonesian payment demo.','QRIS, bank, and e-wallet are simulations. No real money moves.'],['payment','The BOT Chain path.','MetaMask can issue a real ticket after the contract is configured. Never approve a transaction you don’t recognize.'],['payment','A clear final step.','A local demo ticket is not on-chain verified. A real ticket appears only after confirmation.']],tickets:[['ticket-list','All your nights, together.','Your local demo tickets stay on this device. Connect your wallet to load on-chain tickets.'],['ticket-list','Check the details.','Open a ticket to see the owner, ticket identifier, and verification state.'],['ticket-list','Verify before you go.','Real tickets include a transaction hash and explorer link. Demo QR previews are not admission passes.']]};
function startTour(key){close();tour={key,index:0};drawTour()}
// Positions the tour card right beside the element it's explaining (below it, or above if there's no room)
// instead of always pinning it to a corner, so the explanation always sits next to what it describes.
function waitSettle(el,cb){let done=false,last=null,stable=0;const tick=()=>{if(done)return;const r=el.getBoundingClientRect(),key=r.top.toFixed(1)+','+r.left.toFixed(1);if(key===last)stable++;else{stable=0;last=key}if(stable>2){done=true;cb();return}requestAnimationFrame(tick)};requestAnimationFrame(tick);setTimeout(()=>{if(!done){done=true;cb()}},700)}
function positionTourCard(target){
  const card=$('.tour-card');if(!card)return;
  card.classList.remove('tc-above','tc-below','tc-fallback');
  if(!target||!target.getBoundingClientRect().width){card.classList.add('tc-fallback');return}
  waitSettle(target,()=>{
    if(!$('.tour-card'))return;
    const r=target.getBoundingClientRect();
    if(!r.width){card.classList.add('tc-fallback');return}
    const margin=18,cw=card.offsetWidth,ch=card.offsetHeight,vw=innerWidth,vh=innerHeight;
    const spaceBelow=vh-r.bottom,spaceAbove=r.top;
    let top,cls;
    if(spaceBelow>=ch+margin||spaceBelow>=spaceAbove){top=Math.min(Math.max(margin,r.bottom+margin),vh-ch-margin);cls='tc-below'}
    else{top=Math.max(margin,r.top-ch-margin);cls='tc-above'}
    let left=r.left+r.width/2-cw/2;left=Math.min(Math.max(margin,left),vw-cw-margin);
    card.style.top=top+'px';card.style.left=left+'px';card.style.bottom='auto';card.style.right='auto';card.classList.add(cls);
  });
}
addEventListener('resize',()=>{if(tour){const step=tours[tour.key][tour.index];positionTourCard($(`[data-tour="${step[0]}"]`))}});
function drawTour(){ $$('.tour-focus').forEach(e=>e.classList.remove('tour-focus'));const steps=tours[tour.key],step=steps[tour.index],target=$(`[data-tour="${step[0]}"]`);if(target&&target.getBoundingClientRect().width){target.classList.add('tour-focus');target.scrollIntoView({block:'center',behavior:'smooth'})}$('#tour-root').innerHTML=`<div class="tour-shade"></div><aside class="tour-card" role="dialog" aria-label="Quick tour" aria-modal="true"><div class="row"><small>${tour.index+1} OF ${steps.length}</small><button class="text-button" data-action="tour-skip">Skip</button></div><h3>${step[1]}</h3><p>${step[2]}</p><div class="row"><button class="text-button" data-action="tour-back" ${tour.index===0?'disabled':''}>Back</button><button class="btn small" data-action="tour-next">${tour.index===steps.length-1?'Done ✓':'Next'}</button></div></aside>`;$('[data-action=tour-next]').focus();positionTourCard(target)}
function endTour(){if(tour)save('tour:'+tour.key,true);tour=null;$('#tour-root').innerHTML='';$$('.tour-focus').forEach(e=>e.classList.remove('tour-focus'))}
function contextTour(key){const origin=path();if(user&&!read('tour:'+key,false)&&!tour&&!$('#modal').open)setTimeout(()=>{if(path()===origin&&!tour&&!$('#modal').open)startTour(key)},450)}
function checkout(){if(!order)return `<section class="container page empty"><h1>Find your ticket first.</h1><p>Choose a seat or ticket tier to start checkout.</p><a class="btn" href="#/discover">Explore concerts</a></section>`;const e=eventBy(order.eventId);return `<section class="container page"><a class="back" href="#/event/${e.slug}"><span>Back to your concert</span></a><div class="co-head"><div><span class="eyebrow">ONE STEP CLOSER</span><h1>Make the night yours.</h1></div><ol class="co-steps" aria-label="Checkout progress"><li class="done"><b><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg></b>Tickets</li><li class="${paid?'done':'now'}"><b>${paid?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg>':'2'}</b>Payment</li><li class="${paid?'now':''}"><b>3</b>Your ticket</li></ol></div><div class="checkout-grid co-grid"><div class="panel co-pay" data-tour="payment"><h2>Choose how to pay.</h2><div class="payment-tabs co-tabs"><button class="${payType==='bot'?'active':''}" data-pay-type="bot"><span class="co-tab-ico"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/></svg></span><span><b>BOT Chain</b><small>On-chain · your wallet</small></span></button><button class="${payType==='indonesia'?'active':''}" data-pay-type="indonesia"><span class="co-tab-ico"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="6" width="17" height="12" rx="2.5"/><path d="M3.5 10h17M7 14.5h4"/></svg></span><span><b>Demo payment</b><small>QRIS, bank or e-wallet</small></span></button></div><div id="payment-content">${paymentContent()}</div></div><aside class="panel co-sum" data-tour="summary"><span class="eyebrow">YOUR NIGHT</span><div class="co-event"><img src="${esc(posterImage(e))}" alt="Artwork for ${esc(e.title)}"><div><h2>${esc(e.title)}</h2><p>${esc(e.artist)}</p><small>${date(e.date)} · ${esc(e.time)} ${tzOf(e)}<br>${esc(e.venue)}, ${esc(e.city)}</small></div></div><div class="summary-list">${(order.items||[order]).map((it,k)=>`<div class="sum-ticket"><span><small>Ticket ${k+1}</small>${esc(spotOf(e,it))}</span><span>${money(it.price)}</span></div>`).join('')}<div><span>Tickets</span><span>${(order.items||[order]).length} × ${(order.items||[order]).every(i=>i.price===(order.items||[order])[0].price)?money((order.items||[order])[0].price):'mixed'}</span></div><div><span>Service fee</span><span class="co-free">Free</span></div><div class="co-total"><span>Total</span><strong>${money(order.price)}</strong></div></div><p class="co-note">Up to ${MAX_PER} tickets per person for each concert. All listed concerts are fictional.</p></aside></div></section>`}
function syncCoSteps(){const li=$$('.co-steps li');if(li.length<3)return;li[1].className=paid?'done':'now';li[1].querySelector('b').innerHTML=paid?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg>':'2';li[2].className=paid?'now':''}
function paymentContent(){queueMicrotask(syncCoSteps);if(paid)return `<div class="co-paid"><span class="co-paid-ico"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg></span><div><span class="status demo">DEMO PAYMENT CONFIRMED</span><h3>Your payment simulation is complete.</h3></div></div><p class="muted spacer">One final step: choose how to issue your ticket.</p><div class="stack spacer"><button class="btn" data-action="issue-demo">Issue local demo ticket</button><button class="btn secondary" data-action="issue-real">Connect MetaMask & issue on-chain</button><p class="notice">Local demo tickets are not recorded on BOT Chain. ${contractAddress?'Real issuance requires wallet approval.':'The real contract address is not configured yet.'}</p></div><div id="transaction-state" role="status"></div>`;
if(payType==='bot')return `<div class="payment-body"><span class="status">${esc(chainConfig.chainName.toUpperCase())}</span><h3 class="spacer">Your wallet. Your ticket.</h3><p class="muted spacer">The ticket is issued straight to your wallet by the Ticketrue contract. Anyone can check it on the explorer.</p><div id="chain-quote" class="co-info">${contractAddress?'Reading the on-chain price…':'Real payment is unavailable until a deployed contract address is configured. No transaction will be requested.'}</div><div class="co-actions"><button class="co-btn wallet${wallet?' on':''}" data-action="wallet"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7.5A2.5 2.5 0 0 1 6.5 5H17v3"/><rect x="4" y="8" width="16" height="11" rx="2.5"/><path d="M16 13.5h.01"/></svg><span>${wallet?esc(short(wallet)):'Connect MetaMask'}</span>${wallet?'<em>Connected</em>':''}</button><button class="btn co-primary" data-action="issue-real">Buy on BOT Chain</button><button class="co-btn" data-action="issue-claim"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="9" width="16" height="11" rx="2"/><path d="M12 9v11M4 13h16"/><path d="M12 9c-1.5-3.5-5-3.5-5-1.2C7 9 9 9 12 9Zm0 0c1.5-3.5 5-3.5 5-1.2C17 9 15 9 12 9Z"/></svg><span>No BOT yet? Claim a free testnet ticket</span></button></div><a class="co-faucet" href="${botLinks.faucet}" target="_blank" rel="noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5s-6 6.4-6 10.5a6 6 0 0 0 12 0c0-4.1-6-10.5-6-10.5Z"/></svg><span>Need testnet BOT? <b>Open the faucet</b></span></a><div id="transaction-state" role="status"></div></div>`;
return `<div class="methods co-methods"><button class="${payment==='qris'?'active':''}" data-payment="qris"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><path d="M14 14h2v2h-2zM18 14h2M14 18h2M18 18h2v2"/></svg><span>QRIS</span></button><button class="${payment==='bank'?'active':''}" data-payment="bank"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 9.5 12 4l8.5 5.5"/><path d="M5.5 10v7M9.5 10v7M14.5 10v7M18.5 10v7M4 19.5h16"/></svg><span>Bank / VA</span></button><button class="${payment==='ewallet'?'active':''}" data-payment="ewallet"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6.5" y="3" width="11" height="18" rx="2.5"/><path d="M10.5 18h3"/></svg><span>E-wallet</span></button></div><div class="payment-body"><span class="status demo">DEMO PAYMENT · NO REAL MONEY</span>${payment==='qris'?`<div class="qr" aria-label="Non-scannable demo QR pattern">${Array.from({length:169},(_,i)=>`<b class="${(i*7+Math.floor(i/13)*3)%5<3?'on':''}"></b>`).join('')}</div><p style="text-align:center;font-size:12px" class="muted">Demo QR preview · <span id="countdown">60</span>s remaining<br>Do not scan or transfer money.</p>`:payment==='bank'?`<label class="spacer">Choose bank<select id="payment-provider"><option>BCA</option><option>BNI</option><option>BRI</option><option>Mandiri</option></select></label><div class="notice spacer row"><span>DEMO-VA-0000-1234</span><button class="text-button" data-action="copy-va">Copy</button></div><small>This reference is deliberately not a valid bank account.</small>`:`<label class="spacer">Choose e-wallet<select id="payment-provider"><option>GoPay</option><option>DANA</option><option>OVO</option><option>ShopeePay</option></select></label><p class="notice spacer">Demo phone: 08xx-xxxx-0000<br>No e-wallet app will be opened or charged.</p>`}</div><button class="btn full" data-action="simulate">Simulate payment success</button><p class="ownership-note">Hackathon simulation — no real payment is processed.</p>`}
function startCountdown(){clearInterval(timer);if(!$('#countdown'))return;let n=60;timer=setInterval(()=>{if(!$('#countdown')){clearInterval(timer);return}$('#countdown').textContent=--n;if(n<=0){clearInterval(timer);$('#payment-content').innerHTML='<h3>Demo payment expired.</h3><p class="muted spacer">Your selection is still saved.</p><button class="btn spacer" data-action="retry-payment">Generate new demo payment</button>'}},1000)}
function paymentRender(){ $('#payment-content').innerHTML=paymentContent();enhanceSelects($('#payment-content'));startCountdown() }
function ownTickets(){return tickets.filter(t=>t.demo?t.profile===user?.email:wallet&&t.owner.toLowerCase()===wallet.toLowerCase())}
const mtIco={cal:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5.5" width="16" height="14" rx="2.5"/><path d="M4 10h16M8.5 3.5v4M15.5 3.5v4"/></svg>',pin:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s6-5.6 6-10.5a6 6 0 0 0-12 0c0 4.9 6 10.5 6 10.5Z"/><circle cx="12" cy="10" r="2.2"/></svg>',wallet:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7.5A2.5 2.5 0 0 1 6.5 5H17v3"/><rect x="4" y="8" width="16" height="11" rx="2.5"/><path d="M16 13.5h.01"/></svg>',refresh:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11a8 8 0 0 0-14.3-4.9L4 8M4 4v4h4M4 13a8 8 0 0 0 14.3 4.9L20 16M20 20v-4h-4"/></svg>'};
function mtCard(t,group=[t]){const e=eventBy(t.eventId),d=e?new Date(e.date+'T12:00:00'):null,day=d?String(d.getDate()).padStart(2,'0'):'--',mon=d?d.toLocaleDateString('en-GB',{month:'short'}):'',left=d?Math.ceil((d-new Date())/864e5):-1,soon=left<0?'Past event':left===0?'Tonight':left===1?'Tomorrow':`In ${left} days`,href=`#/tickets/${esc(t.id)}`,spot=t.seat?t.seat.replace('-',' · '):(t.tier||'General');return `<article class="mt-card${left<0?' is-past':''}"><a class="mt-art" href="${href}" tabindex="-1" aria-hidden="true"><img src="${esc(posterImage(e))}" alt="" loading="lazy"><span class="mt-date"><b>${day}</b>${esc(mon)}</span></a><div class="mt-body"><div class="mt-tags"><span class="mt-status ${t.demo?'demo':'chain'}"><i></i>${t.demo?'Local demo · not on-chain':'On-chain ticket'}</span><span class="mt-soon">${soon}</span>${group.length>1?`<span class="mt-many">${group.length} tickets</span>`:''}</div>${e?.artist?`<p class="mt-artist">${esc(e.artist)}</p>`:''}<h2><a href="${href}">${esc(e?.title||'Concert')}</a></h2><ul class="mt-meta">${e?`<li>${mtIco.cal}${esc(d.toLocaleDateString('en-GB',{weekday:'short'}))}, ${esc(date(e.date))} · ${esc(e.time)} ${tzOf(e)}</li><li>${mtIco.pin}${esc(place(e))}</li>`:''}</ul></div><div class="mt-stub"><small>${group.length>1?'This order':(t.seat?(t.seat.includes('-')?'Section · Seat':'Seat'):'Category')}</small><strong>${group.length>1?esc([...new Set(group.map(x=>x.tier||'Ticket'))].map(v=>`${group.filter(x=>(x.tier||'Ticket')===v).length} × ${v}`).join(' · ')):esc(spot)}</strong><span class="mt-id">${group.length>1?esc(group.length+' e-tickets · '+t.group):esc(t.id)}</span><a class="mt-view" href="${href}">${group.length>1?'View all tickets':'View ticket'}</a></div></article>`}
function ticketsPage(){const list=ownTickets(),orders=[];for(const t of list){const k=t.group||t.id,f=orders.find(o=>o.key===k);if(f)f.items.push(t);else orders.push({key:k,items:[t]})}return `<section class="container page mt-page"><div class="mt-head"><div><span class="eyebrow">THE NIGHTS YOU'RE PART OF</span><h1>My tickets.</h1>${list.length?`<p class="mt-count">${list.length} ticket${list.length===1?'':'s'} in your collection</p>`:''}</div><button class="btn secondary mt-wallet" data-action="sync-tickets">${wallet?mtIco.refresh+'Refresh on-chain tickets':mtIco.wallet+'Connect wallet'}</button></div><div data-tour="ticket-list" class="tickets-list mt-list">${orders.length?orders.map(o=>mtCard(o.items[0],o.items)).join(''):`<div class="empty mt-empty"><span class="mt-empty-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A1.5 1.5 0 0 1 5.5 6h13A1.5 1.5 0 0 1 20 7.5V10a2 2 0 0 0 0 4v2.5a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 16.5V14a2 2 0 0 0 0-4Z"/><path d="M14 6.5v11" stroke-dasharray="1.6 2.2"/></svg></span><h2>No tickets yet.</h2><p>Your next unforgettable night can start here.</p><a class="btn" href="#/discover">Explore concerts</a></div>`}</div>${saveLists()}</section>`}
let tkIndex=0;
function showTicket(n){const deck=$('#tk-deck');if(!deck)return;const cards=[...deck.children],total=cards.length;tkIndex=((n%total)+total)%total;cards.forEach((c,k)=>{let d=(k-tkIndex+total)%total;c.classList.remove('is-active','behind-1','behind-2','is-hidden');c.classList.add(d===0?'is-active':d===1?'behind-1':d===2?'behind-2':'is-hidden');c.toggleAttribute('inert',d!==0);c.setAttribute('aria-hidden',String(d!==0))});const now=$('#tk-now');if(now)now.textContent=tkIndex+1;$$('.tkp-dot').forEach((b,k)=>{b.classList.toggle('on',k===tkIndex);b.setAttribute('aria-selected',String(k===tkIndex))})}
const orderGroup=t=>{const mine=ownTickets();return t.group?mine.filter(x=>x.group===t.group&&x.eventId===t.eventId):[t]};
function ticketCard(e,t,n,total){return `<article class="ticket-detail${n===1?' is-active':''}" id="tk-${esc(t.id)}" data-i="${n-1}"><div class="ticket-top"><div class="row">${brand()}<span class="status ${t.demo?'demo':''}">${t.demo?'LOCAL DEMO':'ON-CHAIN'}</span></div>${total>1?`<span class="tk-seq">Ticket ${n} of ${total}</span>`:''}<p class="eyebrow spacer">ADMIT ONE / ${esc(e.artist)}</p><h1>${esc(e.title)}</h1><p>${date(e.date)} · ${e.time} ${tzOf(e)}</p></div><div class="ticket-bottom"><dl><div><dt>VENUE</dt><dd>${esc(e.venue)}</dd></div><div><dt>${t.seat?'SEAT':'CATEGORY'}</dt><dd>${esc(t.seat?spotOf(e,t):t.tier)}</dd></div><div><dt>TICKET ID</dt><dd>${esc(t.id)}</dd></div><div><dt>OWNER</dt><dd>${esc(t.owner)}</dd></div><div><dt>ISSUED</dt><dd>${new Date(t.issuedAt).toLocaleString()}</dd></div><div><dt>STATUS</dt><dd>${t.demo?'Demo only · Not valid for admission':'Recorded on BOT Chain'+(t.used?' · Used at gate':'')}</dd></div></dl>${t.tx?`<p class="code">${esc(t.tx)}</p><a href="${chainConfig.blockExplorerUrls[0]}/tx/${t.tx}" target="_blank" rel="noreferrer">View transaction on explorer</a>`:'<p style="font-size:13px">No blockchain transaction exists for this local demo ticket.</p>'}<div id="pass-box-${esc(t.id)}" class="pass-box spacer"></div>${t.demo?'':`<div class="resale-box spacer" data-resale-for="${esc(t.id)}">Checking BOT Chain…</div>`}<div class="tk-mini"><button class="tact" type="button" data-action="cal-add" data-ticket="${esc(t.id)}"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="5.5" width="16" height="14" rx="2.5"/><path d="M4 10h16M8.5 3.5v4M15.5 3.5v4"/><path d="M12 13v4M10 15h4"/></svg></span><span class="tact-txt"><b>Add to calendar</b><small>.ics file</small></span></button><button class="tact" type="button" data-action="share-ticket" data-ticket="${esc(t.id)}"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="18" cy="5.5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="18.5" r="2.5"/><path d="m8.2 10.8 7.6-4M8.2 13.2l7.6 4"/></svg></span><span class="tact-txt"><b>Share</b><small>Send to a friend</small></span></button><button class="tact" type="button" data-action="dl-ticket" data-ticket="${esc(t.id)}"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 4v11M7.5 10.5 12 15l4.5-4.5"/><path d="M5 19.5h14"/></svg></span><span class="tact-txt"><b>Download e-ticket</b><small>PDF</small></span></button></div></div></article>`}
function ticketPage(id){const t=ownTickets().find(t=>String(t.id)===id);if(!t)return missing();const e=eventBy(t.eventId),group=orderGroup(t),total=group.length,sum=group.reduce((n,x)=>n+(Number(x.price)||0),0);
return `<section class="container page ticket-page"><a class="back" href="#/tickets"><span>My tickets</span></a>${total>1?`<div class="tk-order"><div><span class="eyebrow">ONE ORDER</span><h2>${total} tickets for ${esc(e.title)}</h2><p>${group.map(x=>esc(x.tier||'Ticket')).filter((v,i,a)=>a.indexOf(v)===i).map(v=>`${group.filter(x=>(x.tier||'Ticket')===v).length} × ${v}`).join(' · ')} · ${money(sum)}</p></div><div class="tk-nav"><span class="tk-pos"><small>Showing</small><b id="tk-now">1</b> / ${total}</span></div></div>`:''}
<div class="tk-deck-wrap${total>1?' has-nav':''}">${total>1?'<button type="button" class="tk-arrow tk-side prev" data-action="tk-move" data-delta="-1" aria-label="Previous ticket"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 6 9 12l6 6"/></svg></button>':''}<div class="tk-deck${total>1?' is-deck':''}" id="tk-deck">${group.map((x,k)=>ticketCard(e,x,k+1,total)).join('')}</div>${total>1?'<button type="button" class="tk-arrow tk-side next" data-action="tk-move" data-delta="1" aria-label="Next ticket"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg></button>':''}</div>${total>1?`<div class="tkp-dots" role="tablist" aria-label="Tickets in this order">${group.map((x,k)=>`<button type="button" class="tkp-dot${k?'':' on'}" data-action="tk-go" data-i="${k}" role="tab" aria-selected="${!k}" aria-label="Ticket ${k+1}"><span>${k+1}</span></button>`).join('')}</div>`:''}
<div class="tk-actions spacer">${t.demo?'<a class="tact-primary" href="#/discover"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/></svg></span><span class="tact-txt"><b>Get an on-chain ticket</b><small>Own a real, verifiable ticket on BOT Chain</small></span></a>':`<button class="tact-primary" data-verify="${t.id}"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3 4.5 6v5.5c0 4.6 3.2 8.2 7.5 9.5 4.3-1.3 7.5-4.9 7.5-9.5V6Z"/><path d="m8.8 12.2 2.2 2.2 4.2-4.4"/></svg></span><span class="tact-txt"><b>Verify on BOT Chain</b><small>Check that this ticket is still yours</small></span></button>`}<div class="tact-grid"><button class="tact" type="button" data-action="preview-machine"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="3.5" width="16" height="11" rx="2"/><path d="M8 18.5h8M10 14.5v4M14 14.5v4"/><path d="m10.5 7 3.5 2-3.5 2Z"/></svg></span><span class="tact-txt"><b>Preview reveal</b><small>Watch it print</small></span></button>${total>1?`<button class="tact" type="button" data-action="dl-order" data-ticket="${esc(t.id)}"><span class="tact-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 4v11M7.5 10.5 12 15l4.5-4.5"/><path d="M5 19.5h14"/></svg></span><span class="tact-txt"><b>Download all ${total}</b><small>One PDF per ticket</small></span></button>`:''}</div></div><div id="verify-result" class="spacer"></div></section>`}
async function issueDemo(){if(busy)return;{const ev=eventBy(order?.eventId);if(ev&&isOff(ev))throw Error('This concert is not available right now.')}if(!user){returnTo='/checkout';go('/login');return}const e=eventBy(order?.eventId);if(!e||!paid)throw Error('Complete a demo payment first.');const owner=wallet||('demo:'+user.email);const items=order.items||[order],have=ownedCount(e);if(have+items.length>MAX_PER)throw Error(have?`You already hold ${have} ticket${have>1?'s':''} for this concert. One person can have up to ${MAX_PER}.`:`One person can have up to ${MAX_PER} tickets for this concert.`);for(const z of new Set(items.map(i=>i.zone))){const zn=zoneOf(e,z),want=items.filter(i=>i.zone===z).length;if(zn&&zoneLeft(e,zn)<want)throw Error(`${zn.name} just sold out. Please pick another area.`)}const group='G-'+crypto.randomUUID().slice(0,6).toUpperCase(),now=new Date().toISOString();const made=items.map(it=>({eventId:e.id,tier:it.tier,tierIndex:it.tierIndex||0,price:it.price,...(it.zone?{zone:it.zone}:{}),id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner,profile:user.email,issuedAt:now,demo:true,group}));tickets.push(...made);save('tickets',tickets);order=null;paid=false;activeZone=null;if(made.length>1)toast(`${made.length} tickets added to My Tickets.`);go('/reveal/'+made[0].id)}
async function issueReal(free=false){if(busy)return;if(!order)throw Error('Choose a seat or ticket tier first.');if((order.items?.length||1)>1)throw Error('The live contract issues one ticket per transaction. Select one seat or tier, then buy again.');busy=true;const current={...order};try{await connectWallet();if(!contractAddress)throw Error('Wallet connected. The '+chainConfig.chainName+' contract is not configured yet, so no payment was requested.');const result=await web3.issueTicket(current,{fiatDemo:paid||free,status:msg=>{$('#transaction-state').innerHTML='<p class="notice spacer">'+esc(msg)+'</p>'}});const t={...current,...result,owner:wallet,profile:user?.email,demo:false,issuedAt:new Date().toISOString()};tickets.push(t);save('tickets',tickets);order=null;paid=false;delete chainAvail[current.eventId];go('/reveal/'+t.id)}finally{busy=false}}
function reveal(id,preview=false){const t=tickets.find(t=>t.id===id),e=eventBy(t?.eventId)||(preview?events.find(x=>!x.draft):null),seat=t&&e?spotOf(e,t):'A · 01',code=t?.id||'TR-PREVIEW',demo=!t||t.demo||preview;
const sparks=Array.from({length:14},(_,i)=>`<i style="--x:${(i*53)%100}%;--y:${(i*37)%90+5}%;--d:${(i%7)*.7}s;--s:${3+(i%3)*2}px"></i>`).join('');
const step=(k,n,title,sub)=>`<li data-step="${k}"><span class="rv-num">${n}</span><span><b>${title}</b><small>${sub}</small></span></li>`;
return `<section class="container page machine-page rv2"><header class="rv-head"><span class="eyebrow">${preview?'CINEMATIC PREVIEW':t?.demo?'LOCAL DEMO EXPERIENCE':'OWNERSHIP CONFIRMED'}</span><h1>${preview?'A little magic before <em>the music.<svg class="about-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em>':'This night is <em>yours.<svg class="about-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em>'}</h1><p>${demo?'A preview of the ticket reveal. No on-chain transaction is implied.':'Your ticket ownership is recorded on BOT Chain.'}</p></header>
<div class="rv-stage" id="rv-stage" data-state="idle"><div class="rv-deco" aria-hidden="true"><i class="rv-beam b1"></i><i class="rv-beam b2"></i><i class="rv-beam b3"></i><i class="rv-glow"></i><i class="rv-floor"></i><div class="rv-sparks">${sparks}</div></div>
<ol class="rv-steps" aria-label="Reveal progress">${step('processing',1,'Processing','Checking your ticket')}${step('printing',2,'Printing','Fresh off the machine')}${step('ready',3,'Ready','Take it, it’s yours')}</ol>
<div class="machine-stage" id="machine-stage"${e?` data-title="${esc(e.title)}" data-meta="${esc(date(e.date)+' · '+e.time+' '+tzOf(e))}" data-seat="${esc(seat)}" data-venue="${esc(place(e))}" data-code="${esc(code)}" data-demo="${demo?1:0}"`:' data-demo="1"'}><div id="machine-fallback" class="fallback-ticket"><span>TICKETRUE / ${demo?'DEMO':'VERIFIED'}</span><strong>${esc(e?.title||'YOUR NEXT NIGHT')}</strong><hr><span>ONE TICKET. ONE UNFORGETTABLE NIGHT.</span></div></div>
<aside class="rv-card"><span class="rv-card-top"><small>${preview?'Sample ticket':'Your ticket'}</small><em class="${demo?'demo':'chain'}">${demo?'Demo':'On-chain'}</em></span><h3>${esc(e?.title||'Your next night')}</h3>${e?.artist?`<p class="rv-artist">${esc(e.artist)}</p>`:''}<dl><div><dt>Date</dt><dd>${e?esc(date(e.date))+' · '+esc(e.time):'—'}</dd></div><div><dt>Venue</dt><dd>${e?esc(e.venue):'—'}</dd></div><div><dt>${t?.seat||preview?'Seat':'Tier'}</dt><dd>${esc(seat)}</dd></div><div><dt>Code</dt><dd class="rv-code">${esc(code)}</dd></div></dl></aside></div>
<div class="rv-status" role="status"><span class="rv-dot" aria-hidden="true"></span><p id="machine-caption">Preparing the ticket machine…</p></div>
<div class="rv-actions"><a class="btn" href="${t?'#/tickets/'+t.id:'#/discover'}">${t?'Reveal my ticket':'Explore concerts'}</a><button class="btn secondary" type="button" data-action="replay-reveal"><span aria-hidden="true">↻</span> Replay</button></div></section>`}
async function loadMachine(){const container=$('#machine-stage');if(!container)return;const setState=st=>{const sg=$('#rv-stage');if(sg)sg.dataset.state=st;const c=$('#machine-caption');if(c)c.textContent=st==='processing'?'Processing your ticket…':st==='printing'?'Printing your ticket…':st==='ready'?'Your ticket is ready. Take it and enjoy the show!':'Getting the machine ready…'};try{if(matchMedia('(prefers-reduced-motion: reduce)').matches)throw Error('Reduced motion');const {mountMachine}=await import('./machine.js');const instance=await mountMachine(container,{onState:setState});if(!container.isConnected){instance.dispose();return}machine=instance;setState('idle');setTimeout(()=>{if(machine===instance)instance.print()},900)}catch{setState('ready');const c=$('#machine-caption');if(c)c.textContent='Your ticket is ready.'}}
function profile(){const initial=esc((user.name||'U').trim().charAt(0).toUpperCase()),mine=tickets.filter(t=>(t.owner||'').toLowerCase()===(wallet||'demo:'+user.email).toLowerCase()),up=mine.filter(t=>{const e=eventBy(t.eventId);return e&&new Date(e.date+'T23:59')>=new Date()}).length;
return `<section class="container page profile-page"><span class="eyebrow">YOUR TICKETRUE</span><div class="pr-head"><span class="pr-avatar" aria-hidden="true">${initial}</span><div class="pr-id"><h1>Hello, ${esc(user.name.split(' ')[0])}.</h1><p>${esc(user.email)}</p></div><div class="pr-stats"><div><strong>${mine.length}</strong><span>Ticket${mine.length===1?'':'s'}</span></div><div><strong>${up}</strong><span>Upcoming</span></div><div><strong>${saved.length}</strong><span>Saved</span></div></div></div><div class="profile-grid"><div class="panel pr-card"><h2>Your profile</h2><div class="pr-identity"><span class="pr-avatar sm" aria-hidden="true">${initial}</span><div><strong>${esc(user.name)}</strong><small>${esc(user.email)}</small></div><em class="pr-badge">Demo profile</em></div><div class="pr-row">${wallet?'<span class="pr-ico on" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A2.5 2.5 0 0 1 6.5 5H17v3"/><rect x="4" y="8" width="16" height="11" rx="2.5"/><path d="M16 13.5h.01"/></svg></span>':'<span class="pr-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A2.5 2.5 0 0 1 6.5 5H17v3"/><rect x="4" y="8" width="16" height="11" rx="2.5"/><path d="M16 13.5h.01"/></svg></span>'}<div class="pr-row-main"><strong>Wallet</strong><small>${wallet?esc(short(wallet)):'Not connected yet'}</small></div><button class="btn secondary pr-btn" data-action="wallet">${wallet?'Manage':'Connect'}</button></div><p class="pr-note">Local demo profile. This is not a production authentication account.</p><button class="pr-logout" data-action="logout"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5v8"/><path d="M7.2 6.2a7.5 7.5 0 1 0 9.6 0"/></svg>Log out</button></div><div class="panel pr-card"><h2>A little guidance</h2><div class="pr-row"><span class="pr-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"/><path d="M12 8.5v4l2.6 1.6"/></svg></span><div class="pr-row-main"><strong>Quick tour</strong><small>Revisit the basics.</small></div><button class="pr-link" data-action="replay">Replay</button></div><div class="pr-row"><span class="pr-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9.5 18h5"/><path d="M10 21h4"/><path d="M12 3a6 6 0 0 1 3.6 10.8c-.6.5-.9 1.1-.9 1.8H9.3c0-.7-.3-1.3-.9-1.8A6 6 0 0 1 12 3Z"/></svg></span><div class="pr-row-main"><strong>All feature tutorials</strong><small>See tips when you open each feature.</small></div><button class="pr-link" data-action="reset-tours">Reset</button></div><div class="pr-row"><span class="pr-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 20V9l7-5 7 5v11"/><path d="M9 20v-6h6v6"/></svg></span><div class="pr-row-main"><strong>Organizer demo</strong><small>Manage fictional events on this device.</small></div><a class="pr-link" href="#/organizer">Open</a></div><div class="pr-row"><span class="pr-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="5" y="3.5" width="14" height="17" rx="2.5"/><rect x="8" y="6.5" width="8" height="6" rx="1"/><path d="M8 16h8"/></svg></span><div class="pr-row-main"><strong>3D ticket reveal</strong><small>Watch the machine print a ticket.</small></div><button class="pr-link" data-action="preview-machine">Preview</button></div></div></div></section>`}
function organizer(){const live=events.filter(e=>!e.draft),revenue=tickets.reduce((n,t)=>n+(Number(t.price)||0),0),orders=[];for(const t of tickets){const k=t.group||t.id,f=orders.find(o=>o.key===k);if(f)f.items.push(t);else orders.push({key:k,items:[t]})}orders.sort((a,b)=>new Date(b.items[0].issuedAt)-new Date(a.items[0].issuedAt));
const stat=(ico,n,label,sub)=>`<div class="og-stat">${ico}<div><strong>${n}</strong><span>${label}</span><small>${sub}</small></div></div>`;
return `<section class="container page og-page"><div class="og-head"><div><span class="eyebrow">ORGANIZER · LOCAL DEMO</span><h1>Your stages.</h1><p>Create, edit and publish fictional concerts for this device.</p></div><div class="og-head-actions"><a class="btn secondary og-btn" href="#/dashboard">Sales dashboard</a><button class="btn og-btn" data-action="new-event">Create event <span aria-hidden="true">+</span></button></div></div>
<p class="og-note"><span aria-hidden="true">i</span>Changes are stored on this device only. Publishing here updates the local catalog; it does not create an on-chain event.</p>
<div class="og-stats">${stat('<span class="og-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="5.5" width="16" height="14" rx="2.5"/><path d="M4 10h16M8.5 3.5v4M15.5 3.5v4"/></svg></span>',events.length,'Events',`${live.length} published · ${events.length-live.length} draft`)}${stat('<span class="og-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A1.5 1.5 0 0 1 5.5 6h13A1.5 1.5 0 0 1 20 7.5V10a2 2 0 0 0 0 4v2.5a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 16.5V14a2 2 0 0 0 0-4Z"/></svg></span>',tickets.length,'Tickets issued',`${orders.length} order${orders.length===1?'':'s'} on this device`)}${stat('<span class="og-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3v18"/><path d="M16.5 7.5c0-1.9-2-3-4.5-3S7.5 5.6 7.5 7.5 9.5 10 12 10.5s4.5 1.1 4.5 3-2 3-4.5 3-4.5-1.1-4.5-3"/></svg></span>',money(revenue),'Demo revenue','Sum of ticket prices')}${stat('<span class="og-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/></svg></span>',tickets.filter(t=>!t.demo).length,'On-chain tickets','Cached from BOT Chain')}</div>
<div class="og-card"><div class="og-card-head"><h2>Events</h2><span>${events.length} total</span></div><div class="og-list">${events.map(e=>{const cap=venueCap(e),sold=cap-venueLeft(e),pct=cap?Math.round(sold/cap*100):0;return `<div class="og-row"><img class="og-thumb" src="${esc(posterImage(e))}" alt="" loading="lazy"><div class="og-main"><strong>${esc(e.title)}</strong><small>${esc(e.artist)}</small></div><div class="og-when"><b>${esc(date(e.date))}</b><small>${esc(e.time)} ${tzOf(e)} · ${esc(e.city)}</small></div><span class="og-pill map">${esc(layoutOf(e).label)}</span><div class="og-sold"><div class="og-bar"><i style="width:${pct}%"></i></div><small>${sold.toLocaleString('en-GB')} / ${cap.toLocaleString('en-GB')} sold</small></div><span class="og-pill ${e.draft?'draft':'live'}"><i></i>${e.draft?'Draft':'Published'}</span><div class="og-acts"><a class="og-link" href="#/event/${esc(e.slug)}">View</a><button class="og-edit" data-edit-event="${e.id}">Edit</button></div></div>`}).join('')}</div></div>
<div class="og-card"><div class="og-card-head"><h2>Ticket activity</h2><span>${tickets.length} ticket${tickets.length===1?'':'s'}</span></div>${orders.length?`<div class="og-list">${orders.slice(0,12).map(o=>{const t=o.items[0],e=eventBy(t.eventId),sum=o.items.reduce((n,x)=>n+(Number(x.price)||0),0),cats=[...new Set(o.items.map(x=>x.tier||'Ticket'))].map(v=>`${o.items.filter(x=>(x.tier||'Ticket')===v).length} × ${esc(v)}`).join(' · ');return `<div class="og-row act">${e?`<img class="og-thumb sm" src="${esc(posterImage(e))}" alt="" loading="lazy">`:'<span class="og-thumb sm"></span>'}<div class="og-main"><strong>${esc(e?.title||'Event '+t.eventId)}</strong><small>${cats}</small></div><div class="og-when"><b>${new Date(t.issuedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}</b><small>${new Date(t.issuedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</small></div><span class="og-code">${o.items.length>1?esc(o.items.length+' tickets · '+t.group):esc(t.id)}</span><b class="og-sum">${money(sum)}</b><span class="og-pill ${t.demo?'draft':'live'}"><i></i>${t.demo?'Local demo':'On-chain'}</span></div>`}).join('')}</div>${orders.length>12?`<p class="og-more">Showing the 12 most recent orders.</p>`:''}`:'<div class="og-empty">No activity yet. Complete a demo checkout to see ticket issuance here.</div>'}</div></section>`}
function eventForm(id){const e=id?eventBy(id):{};dialog(`<h2>${id?'Edit':'Create'} event</h2><form class="stack" id="event-form" data-id="${id||''}"><label>Concert name<input name="title" value="${esc(e.title||'')}" required maxlength="70"></label><label>Artist<input name="artist" value="${esc(e.artist||'')}" required maxlength="60"></label><div class="row"><label>Date<input name="date" type="date" value="${e.date||''}" required></label><label>Starting Price (USD)<input name="price" type="number" value="${e.price||28}" min="0" max="100000" required></label></div><label>Venue<input name="venue" value="${esc(e.venue||'')}" required maxlength="80"></label><div class="row"><label>City<input name="city" value="${esc(e.city||'')}" required maxlength="40"></label><label>Country<select name="country" aria-label="Country">${[...new Set([...countries,countryOf(e)])].sort().map(c=>`<option${c===countryOf(e)?' selected':''}>${esc(c)}</option>`).join('')}</select></label></div><label>Venue map<select name="layout">${Object.entries(VENUES).map(([k,v])=>`<option value="${k}"${(e.layout||'arena')===k?' selected':''}>${esc(v.label)} · ${v.zones.length} ticket categories</option>`).join('')}</select></label><label><input type="checkbox" name="draft" ${e.draft?'checked':''}> Save as draft</label><button class="btn">Save event</button></form>`)}
function aboutChoice(mode='map'){const isMap=mode==='map';const mini=isMap?`<div class="about-mini-venue" aria-hidden="true"><span class="amv-stage">STAGE</span><span class="amv-z a">Floor</span><span class="amv-z b picked">Lower ring<b>✓</b></span><span class="amv-z c">Upper ring</span></div><div class="about-mini-legend"><i></i> Every concert has its own map</div>`:`<div class="about-mini-cart" aria-hidden="true"><div class="amc-row"><span>Lower Tier</span><em>$56</em><b>2</b></div><div class="amc-row"><span>Upper Tier</span><em>$47</em><b>1</b></div><div class="amc-row total"><span>3 tickets</span><strong>$159</strong></div></div><div class="about-mini-legend"><i></i> Up to four tickets per person</div>`;
return `<div class="about-choice-preview"><div class="about-choice-visual">${mini}</div><div class="about-choice-copy"><span class="eyebrow">${isMap?'EVERY VENUE IS DIFFERENT':'ONE CART, ONE CHECKOUT'}</span><h3>${isMap?'See where you will stand.':'Take up to four.'}</h3><p>${isMap?'Arena rings, a club dancefloor, an open-air garden, a festival field, a convention hall, a beach club. Each concert has its own map, and each area is a ticket category with its own price.':'Mix categories in one order, change your mind with plus and minus, and check out once. One person can hold up to four tickets for a concert, bought together or over time.'}</p><a href="#/event/${isMap?'rhythm-echo-fest-2027':'resonance-night-festival'}" class="text-button">${isMap?'Open a venue map':'Try the ticket cart'}</a></div></div>`}
let aboutTimer=null;
const nextNight=()=>{const now=Date.now();return events.filter(e=>!e.draft).map(e=>({e,t:new Date(`${e.date}T${e.time}:00${utcOf(e)}`).getTime()})).filter(x=>x.t>now).sort((x,y)=>x.t-y.t)[0]||null};
const cdHTML=ms=>{const s=Math.max(0,Math.floor(ms/1000)),p=[Math.floor(s/86400),Math.floor(s%86400/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0'));return `<b>${p[0]}</b><i>d</i><b>${p[1]}</b><i>h</i><b>${p[2]}</b><i>m</i><b>${p[3]}</b><i>s</i>`};
const aboutNext=()=>{const n=nextNight();if(!n)return'';const e=n.e;return `<div class="about-next"><span class="about-eq" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><small>NEXT NIGHT</small><strong>${esc(e.title)}</strong><span>${esc(date(e.date).toUpperCase())} · ${esc(e.venue)}</span><div class="about-cd" id="about-countdown" role="timer" aria-label="Time until ${esc(e.title)}">${cdHTML(n.t-Date.now())}</div><a href="#/event/${esc(e.slug)}">Get tickets</a></div>`};
function tickAbout(){const el=$('#about-countdown'),n=nextNight();if(el&&n)el.innerHTML=cdHTML(n.t-Date.now())}
const aboutMarquee=()=>{const g=[...seed,...seed].map(e=>`<span>${esc(e.artist)}</span><i aria-hidden="true">✳</i>`).join('');return `<div class="about-marquee" aria-hidden="true"><div class="about-marquee-track"><div>${g}</div><div>${g}</div></div></div>`};
function about(){return `<section class="about-page"><div class="container about-intro"><div class="about-intro-copy"><span class="eyebrow">THIS IS TICKETRUE</span><h1>For the music.<br>For the moment.<br><em>For you.<svg class="about-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em></h1><p>That first note. A room full of strangers singing the same words. We believe getting there should feel just as good.</p><a class="btn about-cta" href="#/discover">Find your next night</a><ul class="about-perks"><li><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/></svg></span>On-chain ownership</li><li><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3 4.5 6v5.5c0 4.6 3.2 8.2 7.5 9.5 4.3-1.3 7.5-4.9 7.5-9.5V6Z"/><path d="m8.8 12.2 2.2 2.2 4.2-4.4"/></svg></span>Fair, capped resale</li><li><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A1.5 1.5 0 0 1 5.5 6h13A1.5 1.5 0 0 1 20 7.5V10a2 2 0 0 0 0 4v2.5a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 16.5V14a2 2 0 0 0 0-4Z"/></svg></span>Up to 4 tickets per person</li></ul></div><figure class="about-photo"><img src="./assets/hero.webp" alt="Blue concert lights above a crowd gathered for a live show">${aboutNext()}<svg class="about-badge" viewBox="0 0 120 120" aria-hidden="true" focusable="false"><defs><path id="about-ring" d="M60,60 m-44,0 a44,44 0 1,1 88,0 a44,44 0 1,1 -88,0"/></defs><g class="about-ring"><text font-size="10.5" font-weight="700" letter-spacing="2"><textPath href="#about-ring" textLength="272" lengthAdjust="spacing">LIVE ✳ LOUD ✳ TOGETHER ✳ </textPath></text></g><circle cx="60" cy="60" r="27" fill="#F9A12B"/><text x="60" y="67" text-anchor="middle" font-size="24" font-weight="700" fill="#0c2d50">t.</text></svg><figcaption><span>THE CROWD. THE SOUND. THE MOMENT.</span><strong>Be part of it.</strong></figcaption></figure></div>${aboutMarquee()}<div class="about-facts"><div class="container"><div><strong data-count="6" data-pad="2">06</strong><span>Fictional concerts.<br>A whole range of sound.</span></div><div><strong data-count="6" data-pad="2">06</strong><span>Venue maps.<br>Every concert its own.</span></div><div><strong data-count="4" data-pad="2">04</strong><span>Tickets per person.<br>Enough for the whole crew.</span></div></div></div><section class="container about-choose"><div class="about-heading"><div><span class="eyebrow">A LITTLE CHOICE GOES A LONG WAY</span><h2>How do you like<br>to feel the music?</h2></div><div class="about-switch" role="group" aria-label="Explore venue maps"><button class="active" data-about-mode="map" aria-pressed="true">See the map</button><button data-about-mode="cart" aria-pressed="false">Add your tickets</button></div></div><div id="about-choice">${aboutChoice()}</div></section><section class="about-trust"><div class="container about-trust-grid"><div class="about-ticket" aria-label="Example local demo ticket"><div class="row"><span class="brand">${icon('ticket')} ticketrue.</span><span class="status demo">DEMO</span></div><span class="eyebrow">ONE NIGHT. ALL THE FEELINGS.</span><h3>SOUND WAVE<br>NUSANTARA</h3><p>SHEILA ON 7 · NOAH / 3 NOV 2026</p><div class="about-ticket-stub"><div><small>YOUR SEAT</small><strong>A · 01</strong></div><div><small>YOUR MOMENT</small><strong>Admit one</strong></div></div><small>Illustrative demo · Not an admission pass</small></div><div class="about-trust-copy"><span class="eyebrow">MORE THAN A CONFIRMATION EMAIL</span><h2>A ticket you hold.<br><em>Ownership you can check.<svg class="about-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em></h2><p>Choose your concert, try a familiar checkout, and keep everything together in My Tickets. QRIS, bank, and e-wallet payments are simulations here.</p><div class="about-proof"><span>${icon('shield')}</span><div><h3>A clearer kind of trust.</h3><p>With a configured contract, BOT Chain records ownership and gives your ticket a transaction you can verify.</p></div></div><p class="notice about-note"><span aria-hidden="true">i</span>${contractAddress?'Contract configured. Check your ticket’s verification details.':'On-chain issuance is not active yet. Local demo tickets are clearly marked and are not blockchain records.'}</p><a class="about-pill-link" href="https://botchain.ai" target="_blank" rel="noreferrer">Meet BOT Chain</a></div></div></section><section class="container about-encore-wrap"><div class="about-encore"><i class="about-encore-glow" aria-hidden="true"></i><div class="about-encore-copy"><span class="eyebrow">THE LITTLE DETAILS MATTER</span><h2>Even your ticket<br>gets an <em>entrance.<svg class="about-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em></h2><p>A cinematic machine. A ticket that slides into view.<br>A small moment before the big one.</p></div><a class="about-reveal-link" href="#/machine"><span class="about-play" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 5.4c0-1.1 1.2-1.8 2.1-1.2l10.2 6.6c.9.6.9 1.9 0 2.4L10.1 19.8c-.9.6-2.1-.1-2.1-1.2Z"/></svg></span><span>Preview the 3D reveal<small>Take a look before choosing your concert</small></span></a></div></section></section>`}

function legal(type){const isP=type==='privacy';const keys=Object.keys(localStorage).filter(k=>k.startsWith('tr2:'));return `<section class="container page lg-page"><div class="lg-head"><div><span class="eyebrow">${isP?'PRIVACY':'TERMS'} · DEMO PROTOTYPE</span><h1>${isP?'Your privacy.':'Demo terms.'}</h1><p class="lg-lede">${isP?'What this prototype keeps, where it keeps it, and what it will never ask you for.':'The short version: everything here is a demo, and nothing costs real money.'}</p></div><nav class="lg-switch" aria-label="Legal pages"><a href="#/privacy" class="${isP?'on':''}"${isP?' aria-current="page"':''}>Privacy</a><a href="#/terms" class="${isP?'':'on'}"${isP?'':' aria-current="page"'}>Terms</a></nav></div><div class="lg-grid">${isP?'<article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3.5" y="5" width="17" height="11" rx="2"/><path d="M8 20h8M12 16v4"/></svg></span><h3>Stored in your browser</h3><p>Your demo profile, local ticket records, organizer changes and tutorial preferences live in this browser only. Passwords are never stored or sent anywhere.</p></article><article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3 4.5 6v5.5c0 4.6 3.2 8.2 7.5 9.5 4.3-1.3 7.5-4.9 7.5-9.5V6Z"/><path d="m8.8 12.2 2.2 2.2 4.2-4.4"/></svg></span><h3>Your wallet stays yours</h3><p>Wallet connection is handled by MetaMask. Ticketrue will never ask for your recovery phrase or private keys.</p></article><article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/></svg></span><h3>The blockchain is public</h3><p>Real blockchain transactions can be read by anyone. Never put personal details in anything you send on-chain.</p></article><article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3.5" y="4.5" width="17" height="15" rx="2.5"/><circle cx="9" cy="10" r="1.8"/><path d="m20.5 16-5-5-8 8.5"/></svg></span><h3>Fictional artwork</h3><p>Concert posters and artwork are made for this demo and do not depict a real event.</p></article>':'<article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9.5 3.5h5M10 3.5v5.5L4.8 18a1.6 1.6 0 0 0 1.4 2.5h11.6a1.6 1.6 0 0 0 1.4-2.5L14 9V3.5"/><path d="M7.5 14h9"/></svg></span><h3>A hackathon prototype</h3><p>All six concerts, artists, venues, inventory counts and prices are fictional. No ticket grants admission to a real event.</p></article><article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3.5" y="6" width="17" height="12" rx="2.5"/><path d="M3.5 10h17M7 14.5h4"/></svg></span><h3>Payments are simulated</h3><p>QRIS, bank and e-wallet payments are simulations. Never transfer real money using this demo.</p></article><article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A1.5 1.5 0 0 1 5.5 6h13A1.5 1.5 0 0 1 20 7.5V10a2 2 0 0 0 0 4v2.5a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 16.5V14a2 2 0 0 0 0-4Z"/></svg></span><h3>Demo tickets stay local</h3><p>Local demo tickets are records in your browser, not on BOT Chain.</p></article><article class="lg-card"><span class="lg-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="m8.5 12.5 2.4 2.4 4.6-5"/></svg></span><h3>On-chain needs your approval</h3><p>The blockchain path needs a configured contract and your explicit approval in MetaMask. Testnet tokens have no monetary value.</p></article>'}</div>${isP?`<div class="lg-data"><div><h3>Data on this device</h3><p>${keys.length?`${keys.length} item${keys.length===1?'':'s'} saved by Ticketrue in this browser, including your profile, tickets and saved concerts.`:'Nothing is saved by Ticketrue in this browser right now.'}</p></div><button class="lg-clear" data-action="clear-local" ${keys.length?'':'disabled'}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9.5 7V4.5h5V7M6.5 7l1 13h9l1-13"/></svg>Clear local data</button></div>`:''}<p class="lg-foot">Questions? Ask Rue, the assistant in the corner of the screen.</p></section>`}
function missing(){return '<section class="container page empty"><h1>This page missed the encore.</h1><p>The event or ticket could not be found.</p><a class="btn" href="#/discover">Back to concerts</a></section>'}
async function connectWallet(){wallet=await web3.connectWallet();shell();toast('MetaMask connected: '+short(wallet));return wallet}
function walletDialog(){dialog(`<span class="eyebrow">${esc(chainConfig.chainName.toUpperCase())}</span><h2 class="spacer">Connect your wallet.</h2><p>Approve the connection in MetaMask, then switch to ${esc(chainConfig.chainName)} when prompted.</p><p class="notice">Ticketrue will never ask for your Secret Recovery Phrase.</p><div class="stack spacer"><button class="btn" data-action="connect">${wallet?'Reconnect MetaMask':'Connect MetaMask'}</button>${wallet?`<code class="code">${esc(wallet)}</code><button class="text-button" data-action="disconnect">Disconnect in Ticketrue</button>`:''}</div><div id="wallet-error" class="inline-error spacer" role="alert"></div>`)}
const ago=t=>{const s=Math.max(0,Math.round((Date.now()-t)/1000));return s<60?'just now':s<3600?Math.floor(s/60)+'m ago':s<86400?Math.floor(s/3600)+'h ago':Math.floor(s/86400)+'d ago'};
const bot=wei=>{const n=Number(wei)/1e18;return (n>=1?n.toFixed(2):n.toPrecision(4)).replace(/\.?0+$/,'')+' BOT'};
async function loadQuote(){if(!$('#chain-quote')||!contractAddress||!order)return;const snap=order;try{const q=await web3.quote(snap);if(order!==snap||!$('#chain-quote'))return;$('#chain-quote').innerHTML=q.taken?'That seat is already taken on-chain.':q.remaining===0n?'Sold out on-chain.':`<strong>${bot(q.price)}</strong> · ${q.remaining} left on-chain · plus network fee`}catch{if($('#chain-quote'))$('#chain-quote').textContent='This event is not open on-chain yet.'}}
async function loadAvailability(e){if(!contractAddress||!e)return;try{const av=await web3.chainAvailability(e);chainAvail[e.id]=av;if(av.live&&$('.selector')&&eventBy(path().split('/')[2])?.id===e.id)$('.selector').outerHTML=selectorBlock(e)}catch{}}
async function loadLive(){const box=$('#live-chain');if(!box||!contractAddress)return;try{const r=await web3.activity(5);if(!$('#live-chain'))return;box.hidden=false;countTo($('#live-count'),r.issued,{from:parseInt($('#live-count').textContent)||0});$('#live-list').innerHTML=r.items.length?r.items.map(i=>`<li><span>${esc(short(i.owner))}</span><span>${esc(eventBy(i.eventId)?.title||'Event '+i.eventId)}</span><span>${i.at?ago(i.at):''}</span><a href="${chainConfig.blockExplorerUrls[0]}/tx/${esc(i.tx)}" target="_blank" rel="noreferrer" aria-label="View transaction on explorer">View</a></li>`).join(''):'<li class="live-empty">No tickets yet. Be the first on-chain.</li>'}catch{}}
const toWei=s=>{const v=String(s).trim();if(!/^\d*\.?\d+$/.test(v))throw Error('Enter a valid BOT amount.');const [i,f='']=v.split('.');return BigInt(i||'0')*10n**18n+BigInt((f+'0'.repeat(18)).slice(0,18))};
const txStatus=sel=>msg=>{const el=$(sel);if(el)el.innerHTML='<p class="notice spacer">'+esc(msg)+'</p>'};
async function syncTickets(){const chainTickets=await web3.getWalletTickets();tickets=[...tickets.filter(t=>t.demo||t.owner.toLowerCase()!==wallet.toLowerCase()),...chainTickets.map(t=>({...tickets.find(old=>!old.demo&&old.id===t.id),...t,tier:tierName(eventBy(t.eventId),t.tierIndex)||t.tier}))];save('tickets',tickets)}
async function loadResaleBox(t){const box=$(`[data-resale-for="${t.id}"]`);if(!box||!contractAddress)return;try{const info=await web3.ticketInfo(t.id);let html;if(info.used)html='<strong>Checked in.</strong> This ticket was used at the gate and can no longer be transferred.';else if(info.paid===0n)html='Free claimed tickets can’t be resold. Only tickets that were paid for can be listed.';else if(info.listed>0n)html=`<strong>Listed for ${bot(info.listed)}.</strong> Buyers can see it on the Resell page.<div class="actions spacer"><button class="btn secondary" data-action="resale-cancel" data-ticket="${esc(t.id)}">Cancel listing</button></div>`;else html=`<strong>Resell this ticket.</strong> The price can’t be higher than the ${bot(info.paid)} you paid. 5% goes to the organizer.<form class="row spacer" id="resale-form-${esc(t.id)}" data-resale-form data-ticket="${esc(t.id)}"><input name="price" inputmode="decimal" placeholder="Price in BOT" value="${esc(String(Number(info.paid)/1e18))}" aria-label="Resale price in BOT"><button class="btn secondary">List for resale</button></form>`;box.innerHTML=html+`<div id="resale-state-${esc(t.id)}" role="status"></div>`}catch{}}
async function doResale(id,priceStr){const st='#resale-state-'+id;try{await web3.listForResale(id,toWei(priceStr),txStatus(st));toast('Listed for resale.');await loadResaleBox({id})}catch(err){toast(err.message||'Could not list the ticket.');if($(st))$(st).innerHTML='<p class="notice error spacer">'+esc(err.message||'')+'</p>'}}
const resaleRow=(l,full)=>{const e=eventBy(l.eventId),mine=wallet&&l.owner.toLowerCase()===wallet.toLowerCase();return `<div class="resale-row"><span><strong>${full?esc(e?.title||'Event '+l.eventId)+' · ':''}${esc(l.seat?'Seat '+l.seat:(e?.tiers[l.tierIndex]||'Ticket'))}</strong><small>${full&&e?esc(date(e.date))+' · '+esc(e.city)+' · ':''}Ticket #${esc(l.id)} · seller ${esc(short(l.owner))}</small></span><b>${bot(l.listed)}</b>${mine?'<span class="resale-yours">Your listing</span>':`<button class="btn secondary" data-action="resale-buy" data-ticket="${esc(l.id)}" data-price="${l.listed}">Buy</button>`}</div>`};
async function loadMarket(e){if(!$('#resale-market')||!contractAddress||!e)return;try{const list=await web3.listings(e.id),box=$('#resale-market');if(!box)return;if(!list.length){box.hidden=true;return}box.hidden=false;box.innerHTML='<div class="row"><h3>Verified resale</h3><small>Capped at what the seller paid</small></div>'+list.map(l=>resaleRow(l,false)).join('')+'<div id="market-state" role="status"></div>'}catch{}}
const demoMode=()=>!contractAddress;
const seedListings=()=>[{tid:'DEMO-RS-1',eventId:1,zone:'ring-1f',tierIndex:2,tier:'1F Seating',price:33,paid:34,seller:'fan.9f3a'},{tid:'DEMO-RS-2',eventId:5,zone:'upper',tierIndex:2,tier:'Upper Tier',price:44,paid:47,seller:'fan.c71b'},{tid:'DEMO-RS-3',eventId:6,zone:'deck',tierIndex:1,tier:'Sunset Deck',price:43,paid:45,seller:'fan.02de'}];
let listings=read('listings',null);if(!Array.isArray(listings)){listings=seedListings();save('listings',listings)}
const pctOff=(face,price)=>{const p=Math.round((1-Number(price)/Number(face))*100);return p>0?'−'+p+'% vs face':'At face value'};
const tierName=(e,i)=>e?.mode==='seat'?seatZones[i]?.name:e?.tiers?.[i];
const spotOf=(e,x)=>x.seat?(x.seat.includes('-')?`${x.tier||'Seat'} · Section ${x.seat.split('-')[0]} · Seat ${x.seat.split('-')[1]}`:(x.tier?x.tier+' · ':'')+'Seat '+x.seat):(x.tier||tierName(e,x.tierIndex)||'Ticket');
const rsTones=['amber','blue','navy','cream'];
const rsCard=x=>{const e=eventBy(x.eventId),d=e?new Date(e.date+'T12:00:00'):null,day=d?String(d.getDate()).padStart(2,'0'):'--',mon=d?d.toLocaleDateString('en-GB',{month:'short'}):'',long=d?d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+', '+e.time:'';return `<article class="rs-row tile-${rsTones[(x.i||0)%rsTones.length]}"><div class="rs-thumb" aria-hidden="true">${e?`<img src="${esc(posterImage(e))}" alt="" loading="lazy">`:''}<span class="rs-dchip"><b>${day}</b>${esc(mon)}</span></div><div class="rs-main"><h3>${esc(e?.title||'Event '+x.eventId)}</h3><p>${esc(long)}</p><p>${e?esc(place(e)):''}</p></div><div class="rs-seat"><strong>${esc(x.spot)}</strong><span>${esc(x.detail)}</span><em class="rs-badge seller">${esc(x.badge)}</em></div><div class="rs-priceblock"><small>Resale price</small><div class="rs-pline"><strong>${esc(x.price)}</strong>${x.cheaper?`<s>${esc(x.face)}</s>`:''}</div><em class="rs-badge ${x.cheaper?'save':'plain'}">${esc(x.note)}</em></div><div class="rs-act">${x.action}</div></article>`};
const demoCard=(l,i=0)=>{const e=eventBy(l.eventId),mine=tickets.some(t=>t.id===l.tid&&ownTickets().includes(t)),cheaper=l.price<l.paid;return rsCard({i,eventId:l.eventId,spot:spotOf(e,l),detail:'1 ticket · '+l.tid,badge:mine?'Your listing':l.seller+' · demo seller',price:money(l.price),face:money(l.paid),cheaper,note:cheaper?money(l.paid-l.price)+' cheaper':'Face value',action:mine?`<button class="btn rs-btn" data-action="demo-sim-sale" data-ticket="${esc(l.tid)}">Simulate a buyer</button><button class="text-button rs-cancel" data-action="demo-resale-cancel" data-ticket="${esc(l.tid)}">Cancel listing</button>`:`<button class="btn rs-btn" data-action="demo-resale-buy" data-ticket="${esc(l.tid)}">Buy ticket</button>`})};
const chainCard=(l,i=0)=>{const e=eventBy(l.eventId),mine=wallet&&l.owner.toLowerCase()===wallet.toLowerCase(),cheaper=l.listed<l.paid;return rsCard({i,eventId:l.eventId,spot:spotOf(e,l),detail:'1 ticket · #'+l.id,badge:mine?'Your listing':short(l.owner)+' · verified on-chain',price:bot(l.listed),face:bot(l.paid),cheaper,note:cheaper?bot(l.paid-l.listed)+' cheaper':'Face value',action:mine?'<span class="resale-yours">Your listing</span>':`<button class="btn rs-btn" data-action="resale-buy" data-ticket="${esc(l.id)}" data-price="${l.listed}">Buy ticket</button>`})};
const rsMine=(t,body)=>{const e=eventBy(t.eventId),d=e?new Date(e.date+'T12:00:00'):null,day=d?String(d.getDate()).padStart(2,'0'):'--',mon=d?d.toLocaleDateString('en-GB',{month:'short'}):'';return `<article class="rs-mine sm-card"><div class="sm-art"><img src="${esc(posterImage(e))}" alt="" loading="lazy"><span class="sm-date"><b>${day}</b>${esc(mon)}</span></div><div class="rs-mine-info"><div class="sm-tags"><span class="sm-seat">${esc(spotOf(e,t))}</span>${t.demo?'<span class="sm-demo">Demo</span>':'<span class="sm-chain">On-chain</span>'}</div>${e?.artist?`<p class="mt-artist">${esc(e.artist)}</p>`:''}<h3>${esc(e?.title||'Concert')}</h3>${e?`<ul class="mt-meta"><li>${mtIco.cal}${esc(date(e.date))} · ${esc(e.time)} ${tzOf(e)}</li><li>${mtIco.pin}${esc(place(e))}</li></ul>`:''}<p class="sm-id">Ticket ${esc(t.id)}</p><dl class="sm-facts"><div><dt>You paid</dt><dd>${money(Number(t.price)||0)}</dd></div><div><dt>Resale cap</dt><dd>${money(Number(t.price)||0)}</dd></div><div><dt>Show</dt><dd>${(()=>{if(!d)return '—';const n=Math.ceil((d-new Date())/864e5);return n<0?'Past':n===0?'Tonight':n===1?'Tomorrow':'In '+n+' days'})()}</dd></div></dl><ol class="sm-steps" aria-label="How resale works"><li><b>1</b>You list it</li><li><b>2</b>A fan pays</li><li><b>3</b>Ticket moves to them</li></ol></div><div class="rs-mine-act">${body}</div></article>`};
const demoMineBody=t=>{const l=listings.find(x=>x.tid===t.id);if(l)return `<div class="sm-listed"><span class="sm-live"><i></i>Listed · waiting for a buyer</span><strong>${money(l.price)}</strong><small>Cap ${money(l.paid)} · you receive ${money(Math.floor(l.price*.95))}</small><div class="rs-acts"><button class="btn secondary" data-action="demo-sim-sale" data-ticket="${esc(t.id)}">Simulate a buyer</button><button class="text-button" data-action="demo-resale-cancel" data-ticket="${esc(t.id)}">Cancel listing</button></div></div>`;const p=Number(t.price)||0,chip=(v,label)=>`<button type="button" class="chip" data-action="price-chip" data-value="${v}" aria-pressed="${v===p}">${label}</button>`;return `<form class="rs-form sm-form" data-demo-resale data-ticket="${esc(t.id)}" data-cap="${p}"><div class="sm-label"><label for="p-${esc(t.id)}">Your price</label><span>Max ${money(p)}</span></div><div class="rs-price"><span>$</span><input id="p-${esc(t.id)}" name="price" inputmode="numeric" autocomplete="off" value="${p.toLocaleString('en-US')}"></div><div class="rs-chips">${chip(p,'Face value')}${chip(Math.round(p*.9),'−10%')}${chip(Math.round(p*.8),'−20%')}</div><div class="sm-meter" aria-hidden="true"><i data-bar style="width:100%"></i><em>Cap</em></div><dl class="sm-break"><div><dt>Buyer pays</dt><dd data-gross>${money(p)}</dd></div><div><dt>Organizer share · 5%</dt><dd data-fee>− ${money(p-Math.floor(p*.95))}</dd></div><div class="net"><dt>You receive</dt><dd data-net>${money(Math.floor(p*.95))}</dd></div></dl><p class="rs-receive" data-receive hidden></p><button class="btn sm-submit">List for resale</button></form>`};
function updateReceive(f){const cap=Number(f.dataset.cap),v=Number(String(f.elements.price.value).replace(/\D/g,'')),over=v>cap,bad=!v||over,q=x=>f.querySelector(x),out=q('[data-receive]');f.classList.toggle('is-over',over);if(out){out.hidden=!bad;out.classList.toggle('over',over);out.textContent=!v?'Enter a price.':over?'That is above the '+money(cap)+' you paid. Lower it to list.':''}const net=Math.floor(v*.95);if(q('[data-gross]'))q('[data-gross]').textContent=money(v||0);if(q('[data-fee]'))q('[data-fee]').textContent='− '+money((v||0)-net);if(q('[data-net]'))q('[data-net]').textContent=money(net);const bar=q('[data-bar]');if(bar)bar.style.width=Math.min(100,cap?v/cap*100:0)+'%';f.querySelectorAll('[data-action="price-chip"]').forEach(c=>c.setAttribute('aria-pressed',String(Number(c.dataset.value)===v)))}
function demoOwner(){if(!user){returnTo='/resell';go('/login');return null}return wallet||('demo:'+user.email)}
function demoList(tid,raw){const t=tickets.find(x=>x.id===tid&&x.demo);if(!t)throw Error('Ticket not found.');const price=Number(String(raw).replace(/\D/g,''));if(!price)throw Error('Enter a price in USD.');if(price>t.price)throw Error('The price can’t be higher than the '+money(t.price)+' you paid.');if(listings.some(l=>l.tid===tid))throw Error('This ticket is already listed.');listings.push({tid,eventId:t.eventId,seat:t.seat,tier:t.tier,tierIndex:t.tierIndex,price,paid:t.price,seller:t.owner});save('listings',listings);toast('Listed for '+money(price)+'.');render()}
function demoCancel(tid){listings=listings.filter(l=>l.tid!==tid);save('listings',listings);toast('Listing cancelled.');render()}
function demoSimSale(tid){const l=listings.find(x=>x.tid===tid);if(!l)throw Error('Listing not found.');tickets=tickets.filter(t=>t.id!==tid);listings=listings.filter(x=>x.tid!==tid);save('tickets',tickets);save('listings',listings);toast('Sold for '+money(l.price)+'. You receive '+money(Math.floor(l.price*.95))+' after the 5% organizer share.');render()}
function demoBuy(tid){const l=listings.find(x=>x.tid===tid);if(!l)throw Error('That ticket was just sold.');const owner=demoOwner();if(!owner)return;if(tickets.filter(t=>t.eventId===l.eventId&&t.owner.toLowerCase()===owner.toLowerCase()).length>=MAX_PER)throw Error(`You already hold ${MAX_PER} tickets for this concert, the most one person can have.`);if(l.seat&&tickets.some(t=>t.eventId===l.eventId&&t.seat===l.seat))throw Error('That seat is no longer available.');const t={eventId:l.eventId,seat:l.seat,tier:l.tier,tierIndex:l.tierIndex??0,price:l.price,id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner,profile:user.email,issuedAt:new Date().toISOString(),demo:true};tickets.push(t);listings=listings.filter(x=>x.tid!==tid);save('tickets',tickets);save('listings',listings);toast('The ticket is yours, bought at '+money(l.price)+'.');go('/tickets/'+t.id)}
function resell(){const demo=demoMode(),mine=ownTickets().filter(t=>!!t.demo===demo),n=demo?listings.length:null;const sell=demo?(!user?'<div class="rs-empty"><strong>Log in to see your tickets.</strong><p>Demo tickets belong to your demo profile.</p><a class="btn" href="#/login">Log in</a></div>':mine.length?mine.map(t=>rsMine(t,demoMineBody(t))).join(''):'<div class="rs-empty"><strong>You have no tickets to sell yet.</strong><p>Buy a demo ticket first, then come back to list it.</p><a class="btn" href="#/discover">Find a concert</a></div>'):(!wallet?'<div class="rs-empty"><strong>Connect your wallet.</strong><p>We’ll show the tickets you can resell.</p><button class="btn" data-action="wallet">Connect wallet</button></div>':mine.length?mine.map(t=>rsMine(t,`<div class="resale-box" data-resale-for="${esc(t.id)}">Checking BOT Chain…</div>`)).join(''):'<div class="rs-empty"><strong>No on-chain tickets in this wallet.</strong><p>Buy one first, then list it here.</p><a class="btn" href="#/discover">Find a concert</a></div>');
return `<section class="rs-page"><div class="rs-band"><div class="rs-bg" aria-hidden="true"><i class="rs-glow a"></i><i class="rs-glow b"></i><i class="rs-grid-bg"></i></div><div class="container rs-hero"><div class="rs-hero-copy"><span class="eyebrow">FAIR RESALE</span><h1>Can’t make it?<br><em>Pass it on, fairly.<svg class="rs-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em></h1><p>Sell your ticket to another fan without the scalper markup. The price can never go above what you paid.</p>${demo?'<p class="rs-demo"><i></i><span><b>Demo mode</b> · resale is simulated in this browser and switches to BOT Chain when the contract goes live.</span></p>':''}<div class="rs-cta"><button class="btn" data-action="scroll-to" data-target="rs-sell">Sell a ticket</button><button class="btn secondary" data-action="scroll-to" data-target="rs-forsale">Browse tickets</button></div></div><div class="rs-visual"><div class="rs-scalper" aria-hidden="true"><span>Scalper site</span><b>$84</b><em>3× face value</em></div><div class="rs-example" aria-label="Example of the price cap"><span class="rs-ex-label">Example · face value $28</span><div class="rs-ex-row bad"><span>Scalper site</span><b>$84</b></div><div class="rs-bar bad" aria-hidden="true"><i></i></div><div class="rs-ex-row good"><span>Ticketrue ceiling</span><b>$28</b></div><div class="rs-bar good" aria-hidden="true"><i></i><em>Cap</em></div><p>Nobody gets priced out of a night they were meant to see.</p><span class="rs-stamp" aria-hidden="true">Capped at<br>face value</span></div></div></div></div><div class="container rs-rules"><div><span class="rs-rico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3 4.5 6v5.5c0 4.6 3.2 8.2 7.5 9.5 4.3-1.3 7.5-4.9 7.5-9.5V6Z"/><path d="m8.8 12.2 2.2 2.2 4.2-4.4"/></svg></span><b>01</b><strong>Capped price</strong><p>You can’t list above what you paid. The contract refuses anything higher.</p></div><div><span class="rs-rico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3.5 12.5V5A1.5 1.5 0 0 1 5 3.5h7.5l8 8-9 9ZM8 6.5a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3Z"/></svg></span><b>02</b><strong>Instant hand-over</strong><p>Payment and ownership switch hands together, in one step.</p></div><div><span class="rs-rico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 18V6l10-2v12"/><circle cx="6.5" cy="18" r="2.5"/><circle cx="16.5" cy="16" r="2.5"/></svg></span><b>03</b><strong>5% to the show</strong><p>A small share of every resale goes back to the organizer.</p></div></div><div class="container rs-block" id="rs-forsale"><div class="rs-head"><h2>Tickets for sale</h2>${demo?`<span class="rs-count">${listings.length}</span>`:''}<span class="rs-sub">${demo?`${listings.length} ticket${listings.length===1?'':'s'} for sale, updated just now`:'Live from BOT Chain'}</span>${demo&&listings.length<3?'<button class="text-button" data-action="demo-resale-reset">Restore sample listings</button>':''}</div><div id="resale-all" class="rs-list">${demo?(listings.length?listings.map((l,i)=>demoCard(l,i)).join(''):'<div class="rs-empty"><strong>Nothing is listed right now.</strong><p>List one of your tickets, or restore the sample listings.</p></div>'):'<p class="notice">Reading listings from BOT Chain…</p>'}</div></div><div class="container rs-cta-wrap"><div class="rs-cta-card"><span class="rs-cta-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7.5A1.5 1.5 0 0 1 5.5 6h13A1.5 1.5 0 0 1 20 7.5V10a2 2 0 0 0 0 4v2.5a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 16.5V14a2 2 0 0 0 0-4Z"/><path d="M14 6.5v11" stroke-dasharray="1.6 2.2"/></svg></span><div class="rs-cta-text"><h2>Got a ticket you won’t use?</h2><p>List it here in three steps. You set the price, up to what you paid, and the contract takes care of the payment and hands the ticket over.</p></div><div class="rs-cta-btns"><button class="btn rs-ghost" data-action="scroll-to" data-target="rs-sell">View my listings</button><button class="btn" data-action="scroll-to" data-target="rs-sell">Sell my ticket</button></div></div></div><div class="container rs-block" id="rs-sell"><div class="rs-head"><h2>Sell your ticket</h2>${demo?'':`<button class="btn secondary" data-action="sync-tickets">${wallet?'Refresh from chain':'Connect wallet'}</button>`}</div><div id="resale-mine" class="rs-mine-list">${sell}</div></div></section>`}
async function loadResellPage(){if(demoMode())return;const all=$('#resale-all');if(!all)return;try{const list=await web3.listings();if(!$('#resale-all'))return;$('#resale-all').innerHTML=list.length?list.map((l,i)=>chainCard(l,i)).join('')+'<div id="market-state" role="status"></div>':'<div class="rs-empty"><strong>Nothing is listed right now.</strong><p>When someone lists a ticket, it appears here.</p></div>'}catch(err){if($('#resale-all'))$('#resale-all').innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}$$('#resale-mine [data-resale-for]').forEach(b=>loadResaleBox({id:b.dataset.resaleFor}))}
function gate(){return `<section class="container page gate"><span class="eyebrow">GATE CHECK-IN</span><h1>Is this ticket good to go?</h1><p class="muted">Enter a ticket ID to check it on BOT Chain. Gate staff can mark it as used, so it can’t be admitted twice.</p><form id="gate-form" class="row gate-form"><label class="sr-only" for="gate-id">Ticket ID</label><input id="gate-id" name="id" placeholder="Ticket ID or pasted link, e.g. 12" required><button class="btn">Check ticket</button></form><div id="gate-result" role="status" class="spacer"></div></section>`}
async function gateLookup(id){id=String(id).match(/verify\/(\d+)/)?.[1]||String(id).trim();const out=$('#gate-result');if(!out)return;if(!contractAddress){out.innerHTML='<p class="notice">The BOT Chain contract is not configured yet.</p>';return}out.innerHTML='<p class="notice">Checking BOT Chain…</p>';try{const t=await web3.ticketInfo(id);if(!t.exists){out.innerHTML='<div class="gate-card bad"><strong>NO SUCH TICKET</strong><p>Nothing was issued with ID '+esc(id)+'.</p></div>';return}const e=eventBy(t.eventId);out.innerHTML=`<div class="gate-card ${t.used?'bad':'ok'}"><strong>${t.used?'ALREADY USED':'VALID · NOT YET USED'}</strong><h2>${esc(e?.title||'Event '+t.eventId)}</h2><p>${esc(t.seat?'Seat '+t.seat:(e?.tiers[t.tierIndex]||'Ticket'))} · Ticket #${esc(t.id)} · holder ${esc(short(t.owner))}</p><button class="btn" data-action="gate-checkin" data-ticket="${esc(t.id)}" ${t.used?'disabled':''}>Mark as used</button><div id="gate-state" role="status"></div></div>`}catch(err){out.innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}}
const h1Text=()=>{const h=$('#main h1');if(!h)return'';const c=h.cloneNode(true);c.querySelectorAll('br').forEach(b=>b.replaceWith(' '));return c.textContent.replace(/\s+/g,' ').trim()};
let cselN=0;
function enhanceSelects(root){if(!root)return;$$('select:not([data-csel])',root).forEach(sel=>{sel.dataset.csel='1';const id='csel-'+(++cselN),wrap=document.createElement('div'),btn=document.createElement('button'),list=document.createElement('ul');let active=-1;wrap.className='csel';btn.type='button';btn.className='csel-btn';btn.setAttribute('role','combobox');btn.setAttribute('aria-haspopup','listbox');btn.setAttribute('aria-expanded','false');btn.setAttribute('aria-controls',id);const lab=sel.getAttribute('aria-label');if(lab)btn.setAttribute('aria-label',lab);list.id=id;list.className='csel-list';list.setAttribute('role','listbox');list.hidden=true;sel.before(wrap);wrap.append(btn,list,sel);sel.classList.add('csel-native');sel.tabIndex=-1;sel.setAttribute('aria-hidden','true');
const sync=()=>{btn.innerHTML=`<span>${esc(sel.options[sel.selectedIndex]?.textContent||'')}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>`},paint=(scroll=true)=>[...list.children].forEach((li,i)=>{li.classList.toggle('active',i===active);if(i===active){btn.setAttribute('aria-activedescendant',li.id);if(scroll)li.scrollIntoView({block:'nearest'})}});
const open=()=>{list.innerHTML=[...sel.options].map((o,i)=>`<li role="option" id="${id}-${i}" data-i="${i}" aria-selected="${o.selected}" class="${o.selected?'selected':''}">${esc(o.textContent)}</li>`).join('');active=sel.selectedIndex;list.hidden=false;wrap.classList.add('open');btn.setAttribute('aria-expanded','true');paint()},close=()=>{list.hidden=true;wrap.classList.remove('open');btn.setAttribute('aria-expanded','false');btn.removeAttribute('aria-activedescendant')},pick=i=>{if(i<0||i>=sel.options.length)return;sel.selectedIndex=i;sync();close();sel.dispatchEvent(new Event('change',{bubbles:true}))};
btn.addEventListener('click',()=>list.hidden?open():close());
list.addEventListener('mousedown',e=>e.preventDefault());
list.addEventListener('click',e=>{const li=e.target.closest('li');if(li)pick(+li.dataset.i)});
list.addEventListener('mousemove',e=>{const li=e.target.closest('li');if(li&&+li.dataset.i!==active){active=+li.dataset.i;paint(false)}});
btn.addEventListener('keydown',e=>{const n=sel.options.length;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)open();else{active=Math.min(n-1,Math.max(0,active+(e.key==='ArrowDown'?1:-1)));paint()}}else if((e.key==='Home'||e.key==='End')&&!list.hidden){e.preventDefault();active=e.key==='Home'?0:n-1;paint()}else if((e.key==='Enter'||e.key===' ')&&!list.hidden){e.preventDefault();pick(active)}else if(e.key==='Escape'&&!list.hidden){e.stopPropagation();close()}else if(e.key==='Tab')close();else if(e.key.length===1&&e.key!==' '&&!e.ctrlKey&&!e.metaKey&&!e.altKey){const k=e.key.toLowerCase(),opts=[...sel.options],from=(list.hidden?sel.selectedIndex:active)+1;let hit=opts.findIndex((o,i)=>i>=from&&o.textContent.trim().toLowerCase().startsWith(k));if(hit<0)hit=opts.findIndex(o=>o.textContent.trim().toLowerCase().startsWith(k));if(hit>=0){e.preventDefault();if(list.hidden)open();active=hit;paint()}}});
btn.addEventListener('blur',()=>setTimeout(()=>{if(!wrap.contains(document.activeElement))close()},0));
sync()})}
// ---- Ticket pass (QR), calendar, share, image download ----
const baseUrl=()=>location.href.split('#')[0];
const verifyUrl=(id,extra='')=>`${baseUrl()}#/verify/${encodeURIComponent(id)}${extra}`;
const hashQuery=()=>new URLSearchParams(location.hash.split('?')[1]||'');
const anyTicket=id=>tickets.find(t=>String(t.id)===String(id));
let passTimer=null;
function startPassTimer(exp,t){clearInterval(passTimer);const tick=()=>{const left=exp-Math.floor(Date.now()/1000),el=$('#pass-left');if(!el){clearInterval(passTimer);return}if(left<=0){clearInterval(passTimer);renderPass(t,null,'#pass-box-'+t.id);toast('Live pass expired. Sign a new one when you need it.');return}el.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0')};tick();passTimer=setInterval(tick,1000)}
async function renderPass(t,signed=null,sel='#pass-box'){const box=$(sel);if(!box)return;try{const live=!!signed&&!t.demo,url=live?verifyUrl(t.id,`?e=${signed.exp}&s=${signed.sig}`):verifyUrl(t.id),m=await qrMatrix(url);if(!$(sel))return;$(sel).innerHTML=`<div class="pass"><div class="pass-qr">${qrSvg(m,{label:'Ticket QR code'})}</div><div class="pass-info"><span class="eyebrow">${live?'LIVE PASS · SIGNED BY YOUR WALLET':t.demo?'DEMO PASS':'TICKET LINK'}</span><h3>${live?'Show this at the gate.':'Scan to check this ticket.'}</h3><p>${live?'Valid for <b id="pass-left">5:00</b>. It proves you hold the wallet, so a screenshot stops working.':t.demo?'Demo tickets open a demo page and are not valid for admission.':'Anyone can scan this to check the ticket on BOT Chain. Sign a live pass to prove you hold it.'}</p><div class="actions">${t.demo?'':`<button class="btn" data-action="pass-sign" data-ticket="${esc(t.id)}">${live?'Refresh live pass':'Show live pass'}</button>`}<button class="text-button" data-action="copy-link" data-link="${esc(url)}">Copy link</button></div><div id="pass-state" role="status"></div></div></div>`;if(live)startPassTimer(signed.exp,t)}catch{if($(sel))$('#pass-box').innerHTML='<p class="notice">The QR code could not be generated.</p>'}}
const icsText=(t,e)=>{const start=new Date(`${e.date}T${e.time}:00${utcOf(e)}`),end=new Date(start.getTime()+3*3600e3),f=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),q=s=>String(s).replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n');return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Ticketrue//Concert tickets//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${t.id}@ticketrue`,`DTSTAMP:${f(new Date())}`,`DTSTART:${f(start)}`,`DTEND:${f(end)}`,`SUMMARY:${q(e.title+' · '+e.artist)}`,`LOCATION:${q(place(e))}`,`DESCRIPTION:${q((t.seat?'Seat '+t.seat:t.tier)+' · Ticket '+t.id+(t.demo?' (demo ticket)':''))}`,'BEGIN:VALARM','TRIGGER:-PT3H','ACTION:DISPLAY','DESCRIPTION:Your concert starts in 3 hours','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n')};
function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000)}
function addToCalendar(t){const e=eventBy(t.eventId);if(!e)throw Error('Concert not found.');saveBlob(new Blob([icsText(t,e)],{type:'text/calendar;charset=utf-8'}),'ticketrue-'+e.slug+'.ics');toast('Calendar file downloaded.')}
async function shareTicket(t){const e=eventBy(t.eventId);if(!e)throw Error('Concert not found.');const url=baseUrl()+'#/event/'+e.slug,text=`I’m going to ${e.title} on ${date(e.date)}. Get your ticket on Ticketrue.`;if(navigator.share){try{await navigator.share({title:e.title,text,url})}catch(err){if(err.name!=='AbortError')throw err}return}await navigator.clipboard.writeText(text+' '+url);toast('Link copied. Paste it anywhere.')}
function wrapLines(g,text,max,limit){const words=String(text).split(' '),lines=[];let cur='';for(const w of words){const next=cur?cur+' '+w:w;if(g.measureText(next).width>max&&cur){lines.push(cur);cur=w}else cur=next}if(cur)lines.push(cur);return lines.slice(0,limit)}
async function downloadTicketPdf(t){const e=eventBy(t.eventId);if(!e)throw Error('Concert not found.');const url=verifyUrl(t.id),qr=await qrMatrix(url);let paid=t.paid;if(!t.demo&&contractAddress){try{paid=(await web3.ticketInfo(t.id)).paid}catch{}}
const d=new Date(e.date+'T12:00:00'),now=new Date(),fmt=x=>x.toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const blob=buildTicketPdf({title:e.title,artist:e.artist,genre:e.genre,date:d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),time:e.time+' '+tzOf(e),venue:e.venue,city:e.city,ticketType:t.tier||'General admission',seat:t.seat||'',ticketId:String(t.id),holder:t.demo?(t.profile||user?.email||'Demo profile'):t.owner,payment:t.demo?'Demo payment (no real money)':chainConfig.nativeCurrency.symbol+' on '+chainConfig.chainName,amount:t.demo?money(t.price)+' (demo)':(paid?bot(BigInt(paid)):'See the transaction on the explorer'),issued:fmt(new Date(t.issuedAt)),network:t.demo?'Not recorded on-chain':chainConfig.chainName+' (chain ID '+parseInt(chainConfig.chainId,16)+')',contract:t.demo?'':contractAddress,tx:t.demo?'':(t.tx||''),demo:!!t.demo,qr,verifyUrl:url,
steps:['Show this ticket at the entrance, printed or on your phone.',t.demo?'Demo tickets cannot be scanned for entry.':'Staff scan the QR code. It is checked on '+chainConfig.chainName.replace(' Testnet','').replace(' Mainnet','')+'.','Each ticket admits one person, once.',t.demo?'To try the real flow, buy a ticket on the BOT Chain tab.':'To prove it is yours, open My Tickets and show a live pass.'],
terms:[t.demo?'Demo tickets involve no real payment.':'Tickets are bought with BOT and are not refundable in this prototype.','Up to four tickets per person for each concert.','Resale only on Ticketrue, at or below the price paid.','A used ticket is void. A screenshot alone is not proof of holding it.','All events are fictional. Demo tickets are not valid for admission.'],
generated:'Generated '+fmt(now),footerLeft:'Issued by Ticketrue'+(t.demo?' (demo).':' on BOT Chain.')+' Verify this ticket online:'});
saveBlob(blob,'Ticketrue-e-ticket-'+e.slug+'-'+String(t.id).slice(-8)+'.pdf');toast('E-ticket PDF saved.')}

// ---- Public ticket check page ----
function verifyPage(){return `<section class="container page verify-page"><span class="eyebrow">TICKET CHECK</span><h1>Is this ticket real?</h1><p class="muted">This page reads the Ticketrue contract on BOT Chain. No login or wallet needed.</p><div id="verify-card" class="spacer"><p class="notice">Checking BOT Chain…</p></div></section>`}
const vCard=(tone,label,title,lines,extra='')=>`<div class="gate-card ${tone}"><strong>${esc(label)}</strong><h2>${esc(title)}</h2>${lines.map(l=>`<p>${l}</p>`).join('')}${extra}</div>`;
async function loadVerify(id){const box=$('#verify-card');if(!box)return;try{
 if(/^DEMO-/i.test(id)){box.innerHTML=vCard('warn','DEMO TICKET','Not a blockchain ticket',['This is a demo ticket kept in one browser. It is not recorded on BOT Chain and is not valid for admission.']);return}
 if(!contractAddress){box.innerHTML=vCard('warn','NOT CONFIGURED','The contract is not live yet',['This site has no BOT Chain contract configured, so tickets cannot be checked on-chain yet.']);return}
 if(!/^\d+$/.test(id)){box.innerHTML=vCard('bad','NO SUCH TICKET','Unrecognised ticket',['That is not a Ticketrue ticket ID.']);return}
 const t=await web3.ticketInfo(id);if(!$('#verify-card'))return;
 if(!t.exists){box.innerHTML=vCard('bad','NO SUCH TICKET','Nothing was issued with this ID',[`Ticket #${esc(id)} does not exist on this contract.`]);return}
 const q=hashQuery(),exp=q.get('e'),sig=q.get('s');let holder;
 if(sig&&exp){if(Number(exp)<Date.now()/1000)holder={tone:'warn',text:'This live pass has expired. Ask the holder to refresh it.'};else{try{const who=await web3.recoverSigner(web3.passMessage(id,exp),sig);holder=who.toLowerCase()===t.owner.toLowerCase()?{tone:'ok',text:'<b>Holder confirmed.</b> This pass was signed moments ago by the wallet that owns the ticket.'}:{tone:'bad',text:'<b>Signature does not match the ticket owner.</b> Do not admit.'}}catch{holder={tone:'bad',text:'The pass signature could not be checked. Do not admit.'}}}}
 else holder={tone:'warn',text:'No live pass attached. Ownership is on-chain, but the holder is not proven. Ask them to show a live pass.'};
 const e=eventBy(t.eventId),tone=t.used?'bad':holder.tone==='bad'?'bad':'ok',label=t.used?'ALREADY USED':holder.tone==='bad'?'DO NOT ADMIT':'VALID TICKET';
 box.innerHTML=vCard(tone,label,e?.title||'Event '+t.eventId,[`${esc(t.seat?'Seat '+t.seat:(e?.tiers?.[t.tierIndex]||'Ticket'))} · Ticket #${esc(t.id)} · holder ${esc(short(t.owner))}`,holder.text,`<a href="${chainConfig.blockExplorerUrls[0]}/address/${contractAddress}" target="_blank" rel="noreferrer">View contract on the explorer</a>`],`<div class="actions spacer"><button class="btn" data-action="gate-checkin" data-ticket="${esc(t.id)}" ${t.used?'disabled':''}>Mark as used (gate staff)</button></div><div id="gate-state" role="status"></div>`)}
 catch(err){if($('#verify-card'))$('#verify-card').innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}}

// ---- Organizer dashboard ----
function dashboard(){return `<section class="dash-page"><div class="rs-band dash-band"><div class="rs-bg" aria-hidden="true"><i class="rs-glow a"></i><i class="rs-glow b"></i><i class="rs-grid-bg"></i></div><div class="container"><span class="eyebrow">ORGANIZER DASHBOARD</span><h1>Your nights,<br><em>by the numbers.<svg class="about-swoosh" viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M3 12 C 60 4, 120 3, 180 7 S 270 13, 297 5"/></svg></em></h1><p>Sales, resale, gate check-ins and payouts, read straight from the Ticketrue contract on BOT Chain.</p><div id="dash-role" class="dash-role"></div></div></div><div class="container dash-body"><div id="dash-kpis" class="dash-kpis"></div><div id="dash-sales" class="dash-block"></div><div id="dash-publish" class="dash-block"></div><div id="dash-staff" class="dash-block"></div><div id="dash-pay" class="dash-block"></div><div id="dash-state" role="status"></div></div></section>`}
const DICO={"tix": "<path d=\"M4 7.5A1.5 1.5 0 0 1 5.5 6h13A1.5 1.5 0 0 1 20 7.5V10a2 2 0 0 0 0 4v2.5a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 16.5V14a2 2 0 0 0 0-4Z\"/>", "rev": "<path d=\"M12 3v18\"/><path d=\"M16.5 7.5c0-1.9-2-3-4.5-3S7.5 5.6 7.5 7.5 9.5 10 12 10.5s4.5 1.1 4.5 3-2 3-4.5 3-4.5-1.1-4.5-3\"/>", "swap": "<path d=\"M3.5 12.5V5A1.5 1.5 0 0 1 5 3.5h7.5l8 8-9 9ZM8 6.5a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3Z\"/>", "gate": "<rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2.5\"/><path d=\"m8.5 12.5 2.4 2.4 4.6-5\"/>", "bal": "<path d=\"M4 7.5A2.5 2.5 0 0 1 6.5 5H17v3\"/><rect x=\"4\" y=\"8\" width=\"16\" height=\"11\" rx=\"2.5\"/><path d=\"M16 13.5h.01\"/>"};
const dKpi=(n,label,extra='',ico='tix')=>`<div class="dash-kpi"><span class="dk-ico" aria-hidden="true"><svg viewBox="0 0 24 24">${DICO[ico]||''}</svg></span><div><strong>${n}</strong><span>${label}</span>${extra}</div></div>`;
async function loadDashboard(){if(!$('#dash-kpis'))return;
 if(demoMode()){const sold=tickets.filter(t=>t.demo),rev=sold.reduce((s,t)=>s+(Number(t.price)||0),0),by=events.filter(e=>!e.draft).map(e=>({e,n:sold.filter(t=>t.eventId===e.id).length})),max=Math.max(1,...by.map(x=>x.n));
  $('#dash-role').innerHTML='<i></i>DEMO VIEW · numbers come from tickets created in this browser. It switches to live contract data once the contract is deployed.';
  $('#dash-kpis').innerHTML=dKpi(sold.length,'Tickets issued',`<small>across ${by.filter(x=>x.n).length} concert${by.filter(x=>x.n).length===1?'':'s'}</small>`,'tix')+dKpi(money(rev),'Demo sales',`<small>avg ${money(sold.length?Math.round(rev/sold.length):0)} / ticket</small>`,'rev')+dKpi(listings.length,'Resale listings','<small>capped at face value</small>','swap')+dKpi('—','Checked in','<small>after the contract is live</small>','gate');
  const total=Math.max(1,sold.length);$('#dash-sales').innerHTML='<div class="ds-head"><h2>Sales by concert</h2><span>'+sold.length+' tickets · '+money(rev)+'</span></div><div class="ds-list">'+[...by].sort((a,b)=>b.n-a.n).map(({e,n})=>{const r=sold.filter(t=>t.eventId===e.id).reduce((s,t)=>s+(Number(t.price)||0),0),top=n&&n===max;return `<div class="ds-row"><img class="ds-thumb" src="${esc(posterImage(e))}" alt="" loading="lazy"><span class="ds-main"><strong>${esc(e.title)}${top?'<em class="ds-top">Top seller</em>':''}</strong><small>${esc(date(e.date))} · ${esc(e.city)}</small></span><div class="ds-bar-wrap"><div class="dash-bar"><i style="width:${Math.round(n/max*100)}%"></i></div><small>${Math.round(n/total*100)}% of tickets</small></div><span class="ds-num"><b>${n}</b><small>sold</small></span><span class="ds-rev">${money(r)}</span></div>`}).join('')+'</div>';
  $('#dash-publish').innerHTML='<div class="ds-locked"><span class="ds-lock" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="5" y="10.5" width="14" height="10" rx="2.5"/><path d="M8.5 10.5V8a3.5 3.5 0 0 1 7 0v2.5"/></svg></span><div><strong>On-chain tools are locked</strong><p>They unlock after the Ticketrue contract is deployed and its address is set in <code>config.js</code>.</p><div class="ds-chips"><span>Publish events on-chain</span><span>Gate staff check-in</span><span>Withdraw payouts</span></div></div></div>';return}
 $('#dash-kpis').innerHTML='<p class="notice">Reading BOT Chain…</p>';
 try{const list=events.filter(e=>!e.draft),d=await web3.dashboard(list);if(!$('#dash-kpis'))return;const me=!!wallet&&wallet.toLowerCase()===d.organizer.toLowerCase();
  $('#dash-role').innerHTML=me?'<i class="on"></i>YOU ARE THE ORGANIZER':`<i></i>READ-ONLY · organizer wallet is ${esc(short(d.organizer))} ${wallet?'':'<button class="text-button" data-action="wallet">Connect wallet</button>'}`;
  $('#dash-kpis').innerHTML=dKpi(d.issued,'Tickets issued','','tix')+dKpi(bot(d.balance),'Withdrawable balance','','bal')+dKpi(d.resales.count,'Resales',`<small>${bot(d.resales.volume)} traded</small>`,'swap')+dKpi(d.checkins,'Checked in','','gate');
  $('#dash-sales').innerHTML='<div class="rs-head"><h2>Sales by concert</h2></div>'+d.perEvent.map(p=>{const e=eventBy(p.id);if(!e)return'';if(!p.live)return `<div class="dash-row"><span><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}</small></span><span class="dash-off">Not on-chain yet</span></div>`;return `<div class="dash-event"><div class="dash-ehead"><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}${p.demo?' · free demo claims on':''}</small></div>${p.options.map((o,i)=>o?`<div class="dash-row"><span><small>${esc(tierName(e,i)||'Tier '+(i+1))} · ${bot(o.price)}</small></span><div class="dash-bar"><i style="width:${o.capacity?Math.round(Number(o.issued)/Number(o.capacity)*100):0}%"></i></div><b>${o.issued}/${o.capacity}</b></div>`:'').join('')}</div>`}).join('');
  const off=d.perEvent.filter(p=>!p.live);
  $('#dash-publish').innerHTML=!off.length?'':`<div class="rs-head"><h2>Publish on-chain</h2></div>`+(me?off.map(p=>{const e=eventBy(p.id),zs=zonesOf(e),n=zs.length,def=r=>botSuggestion(r);return `<form class="dash-form" data-dash="publish" data-event="${esc(e.id)}"><div class="dash-fhead"><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(layoutOf(e).label)} · ${n} categories</small></div><div class="dash-fields">${zs.map((z,i)=>`<label>${esc(z.name)} · price (BOT)<input name="price${i}" inputmode="decimal" value="${def(zonePrice(e,z))}"></label><label>${esc(z.name)} · tickets<input name="cap${i}" inputmode="numeric" value="${z.cap}"></label>`).join('')}</div>${isMainnet?'':'<label class="dash-check"><input type="checkbox" name="demo" checked> Allow free demo claims (testnet only)</label>'}<button class="btn">Create on-chain</button></form>`}).join(''):'<p class="notice">Connect the organizer wallet to create the remaining concerts on-chain.</p>');
  $('#dash-staff').innerHTML=`<div class="rs-head"><h2>Gate staff</h2></div>${d.staff.length?d.staff.map(a=>`<div class="dash-row"><span><strong>${esc(short(a))}</strong><small>${esc(a)}</small></span>${me?`<button class="text-button" data-action="dash-staff-remove" data-addr="${esc(a)}">Remove</button>`:''}</div>`).join(''):'<p class="notice">No staff added yet. The organizer wallet can always check tickets in.</p>'}${me?'<form class="dash-inline" data-dash="staff"><input name="addr" placeholder="Staff wallet address 0x…" aria-label="Staff wallet address"><button class="btn secondary">Add staff</button></form>':''}`;
  $('#dash-pay').innerHTML=`<div class="rs-head"><h2>Payouts</h2></div><p class="muted">${bot(d.balance)} is ready to withdraw. Primary sales and the 5% resale share collect in the contract.</p>${me?`<form class="dash-inline" data-dash="withdraw"><input name="addr" value="${esc(wallet)}" aria-label="Recipient wallet"><button class="btn">Withdraw</button></form>`:'<p class="notice">Only the organizer wallet can withdraw.</p>'}`}
 catch(err){if($('#dash-kpis'))$('#dash-kpis').innerHTML='<p class="notice error">'+esc(err.message)+'</p>'}}
async function doDash(f,d){const kind=f.dataset.dash,st=txStatus('#dash-state');try{
 if(kind==='publish'){const e=eventBy(f.dataset.event),n=zonesOf(e).length,prices=[],caps=[];for(let i=0;i<n;i++){prices.push(toWei(d.get('price'+i)));const c=Number(d.get('cap'+i));if(!Number.isInteger(c)||c<1)throw Error('Tickets per category must be a whole number of at least 1.');caps.push(c)}const startsAt=Math.floor(new Date(`${e.date}T${e.time}:00${utcOf(e)}`).getTime()/1000);if(startsAt<=Date.now()/1000)throw Error('This concert date has already passed.');await web3.createEventTx(e.id,{seated:false,demo:d.has('demo'),startsAt,prices,caps},st);toast(e.title+' is live on-chain.')}
 else{const a=String(d.get('addr')||'').trim();if(!/^0x[0-9a-fA-F]{40}$/.test(a))throw Error('Enter a valid wallet address.');if(kind==='staff'){await web3.setStaffTx(a,true,st);toast('Gate staff added.')}else{await web3.withdrawTx(a,st);toast('Withdrawal sent.')}}
 await loadDashboard()}catch(err){toast(err.message||'Something went wrong.');if($('#dash-state'))$('#dash-state').innerHTML='<p class="notice error spacer">'+esc(err.message||'')+'</p>'}}
// ---- Availability badges, waitlist, saved concerts ----
let saved=read('saved',[]),waitlist=read('waitlist',[]);const stockCache={},resaleCount={};
function stockState(e){let left,cap;if(contractAddress){const s=stockCache[e.id];if(!s)return{state:'unknown'};if(!s.live)return{state:'soon'};left=s.left;cap=s.cap}else{cap=venueCap(e);left=venueLeft(e)}return{state:left<=0?'sold':left<=Math.max(10,Math.round(cap*.1))?'low':'ok',left,cap}}
const stockBadge=e=>{const s=stockState(e);return s.state==='sold'?'<span class="stock stock-sold">Sold out</span>':s.state==='soon'?'<span class="stock stock-soon">On sale soon</span>':s.state==='low'?`<span class="stock stock-low">Only ${s.left} left</span>`:''};
const isOff=e=>{const s=stockState(e).state;return s==='sold'||s==='soon'};
const heartBtn=e=>{const on=saved.includes(e.id);return `<span class="heart${on?' on':''}" role="button" tabindex="0" data-action="save" data-event="${e.id}" aria-pressed="${on}" aria-label="Save ${esc(e.title)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s-7.5-4.6-7.5-10A4.3 4.3 0 0 1 12 7.8a4.3 4.3 0 0 1 7.5 2.7c0 5.4-7.5 10-7.5 10Z"/></svg></span>`};
function waitlistBox(e){const s=stockState(e).state;if(s!=='sold'&&s!=='soon')return `<div id="waitlist-box" data-event="${e.id}" hidden></div>`;const on=waitlist.includes(e.id),n=demoMode()?listings.filter(l=>l.eventId===e.id):(resaleCount[e.id]||[]),rl=n.length?`<p class="waitlist-resale"><b>${n.length} resale ticket${n.length>1?'s':''}</b> from ${demoMode()?money(Math.min(...n.map(l=>l.price))):bot(n.reduce((m,l)=>l.listed<m?l.listed:m,n[0].listed))}. <a href="#/resell">See resale</a></p>`:'';return `<div id="waitlist-box" class="waitlist" data-event="${e.id}"><span class="eyebrow">${s==='sold'?'SOLD OUT':'NOT ON SALE YET'}</span><h3>${s==='sold'?'Missed it? Get in line.':'Be first in line.'}</h3><p>${s==='sold'?'Tickets come back when someone resells or the organizer adds more.':'Tickets open once the organizer publishes this concert.'}</p>${rl}<button class="btn ${on?'secondary':''}" data-action="wl-toggle" data-event="${e.id}">${on?'✓ On the waitlist · Leave':'Join the waitlist'}</button><small>Saved on this device only.</small></div>`}
function paintStocks(){$$('[data-stock]').forEach(el=>{const e=eventBy(el.dataset.stock);if(e)el.innerHTML=stockBadge(e)});const box=$('#waitlist-box');if(box){const e=eventBy(box.dataset.event);if(e)box.outerHTML=waitlistBox(e)}const sel=$('.selector'),id=path().startsWith('/event/')?eventBy(path().split('/')[2])?.id:null;if(sel&&id){const e=eventBy(id);sel.toggleAttribute('inert',isOff(e));sel.classList.toggle('is-off',isOff(e))}}
async function loadStocks(){const list=events.filter(e=>!e.draft);if(!contractAddress){paintStocks();return}await Promise.all(list.map(async e=>{try{const s=await web3.stockOf(e);stockCache[e.id]=s;if(!s.live||s.left<=0){try{resaleCount[e.id]=await web3.listings(e.id)}catch{}}}catch{}}));paintStocks();const back=list.filter(e=>waitlist.includes(e.id)&&!isOff(e)&&stockState(e).state!=='unknown');if(back.length){waitlist=waitlist.filter(id=>!back.some(e=>e.id===id));save('waitlist',waitlist);toast('Tickets are back: '+back.map(e=>e.title).join(', '))}}
function toggleSaved(id){const on=saved.includes(id);saved=on?saved.filter(x=>x!==id):[...saved,id];save('saved',saved);$$(`[data-action=save][data-event="${id}"]`).forEach(b=>{b.classList.toggle('on',!on);b.setAttribute('aria-pressed',String(!on));const l=b.querySelector('.save-label');if(l)l.textContent=!on?'Saved':'Save'});{const c=$('#saved-count');if(c)c.textContent=saved.length;if(savedOnly&&path()==='/discover')filterEvents()}toast(!on?'Saved to your list.':'Removed from your list.');if($('#save-lists'))$('#save-lists').outerHTML=saveLists()}
function toggleWaitlist(id){const on=waitlist.includes(id);waitlist=on?waitlist.filter(x=>x!==id):[...waitlist,id];save('waitlist',waitlist);toast(on?'Left the waitlist.':'You’re on the waitlist. We’ll flag it here when tickets return.');paintStocks();if($('#save-lists'))$('#save-lists').outerHTML=saveLists()}
function saveLists(){const row=(id,kind)=>{const e=eventBy(id);return e?`<div class="save-row"><a href="#/event/${esc(e.slug)}"><strong>${esc(e.title)}</strong><small>${esc(date(e.date))} · ${esc(e.city)}${kind==='wl'?' · '+(stockState(e).state==='sold'?'sold out':stockState(e).state==='soon'?'not on sale yet':'available'):''}</small></a><button class="text-button" data-action="${kind==='wl'?'wl-toggle':'save'}" data-event="${e.id}">Remove</button></div>`:''};const s=saved.map(id=>row(id,'s')).join(''),w=waitlist.map(id=>row(id,'wl')).join('');if(!s&&!w)return '<div id="save-lists"></div>';return `<div id="save-lists" class="save-lists">${s?`<div class="save-col"><h2>Saved concerts</h2>${s}</div>`:''}${w?`<div class="save-col"><h2>Waitlist</h2>${w}</div>`:''}</div>`}
// ---- Event guide: schedule, venue, FAQ, similar concerts ----
function guideInfo(e){const i=e.info||seed.find(s=>s.id===e.id)?.info;if(i)return i;const [h,m]=String(e.time||'19:00').split(':').map(Number),d=new Date(2000,0,1,h,m-60);return{schedule:[[String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'),'Doors open'],[e.time,e.artist+' · '+e.title]],venue:'',age:'All ages.',bag:'Small bags only.'}}
function eventGuide(e){const i=guideInfo(e),faq=[['What time should I arrive?',`Doors open at ${i.schedule[0][0]} ${tzOf(e)} and the show starts at ${e.time} ${tzOf(e)}. Arriving 30 to 45 minutes after doors open avoids the queue.`],['Who can attend?',i.age],['What can I bring?',i.bag],['Can I resell my ticket?','Yes. On the <a href="#/resell">Resell page</a>, at or below what you paid. The organizer keeps 5% of each resale.',true],['How many tickets can I buy?','Up to four tickets per person for each concert, in one order or several.'],['Is this a real concert?','No. Ticketrue is a prototype. The concerts, artists and venues here are fictional, and demo payments move no real money.']],rel=events.filter(x=>!x.draft&&x.id!==e.id).map(x=>({x,s:(x.city===e.city?2:0)+(x.layout===e.layout?1:0)})).sort((p,q)=>q.s-p.s).slice(0,3).map(p=>p.x);return `<div class="guide"><section class="guide-block gd-card"><header class="gd-head"><span class="gd-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 7v5l3.5 2"/><circle cx="12" cy="13" r="8"/><path d="M9 3h6M12 3v2"/></svg></span><div><span class="eyebrow">THE NIGHT, HOUR BY HOUR</span><h2>Schedule</h2></div></header><div class="gd-chips"><span><b>Doors</b>${esc(i.schedule[0][0])} ${tzOf(e)}</span><span><b>Ends</b>${esc(i.schedule.at(-1)[0])} ${tzOf(e)}</span><span><b>Runs</b>${(()=>{const m=t=>+t.slice(0,2)*60+ +t.slice(3);let d=m(i.schedule.at(-1)[0])-m(i.schedule[0][0]);if(d<0)d+=1440;return Math.floor(d/60)+'h '+(d%60?d%60+'m':'').trim()})()}</span></div><ol class="timeline">${i.schedule.map(([t,l],idx)=>{const main=idx===i.schedule.length-2;return `<li${main?' class="is-main"':''}><span class="tl-dot" aria-hidden="true"><svg viewBox="0 0 24 24">${idx===0?`<rect x="6" y="3.6" width="12" height="16.8" rx="1.8"/><path d="M6 3.6h12"/><circle cx="14.6" cy="12" r=".9" fill="currentColor" stroke="none"/>`:idx===i.schedule.length-1?`<path d="M8.1 20.4V4.2"/><path d="M8.1 5.2h9l-2.3 3.2 2.3 3.2h-9"/>`:`<path d="M10.2 16.6V6.6l6.6-1.4v9.6"/><circle cx="7.9" cy="17" r="2.5"/><circle cx="14.5" cy="15.3" r="2.5"/>`}</svg></span><time>${esc(t)}<small>${tzOf(e)}</small></time><span>${esc(l)}${main?'<em class="tl-tag">Main act</em>':''}</span></li>`}).join('')}</ol><p class="gd-foot">Times are local (${tzOf(e)}) and may shift a little on the night.</p></section><section class="guide-block gd-card"><header class="gd-head"><span class="gd-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 20.5s6-5.6 6-10.5a6 6 0 0 0-12 0c0 4.9 6 10.5 6 10.5Z"/><circle cx="12" cy="10" r="2.2"/></svg></span><div><span class="eyebrow">THE VENUE</span><h2>${esc(e.venue)}</h2></div></header><p class="muted">${esc(i.venue||e.city)}</p><dl class="guide-facts"><div><dt><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20V9l7-5 7 5v11"/><path d="M9 20v-6h6v6"/></svg>City</dt><dd>${esc(e.city)}</dd></div><div><dt><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M3.5 12h17M12 3.5c2.3 2.4 3.5 5.3 3.5 8.5S14.3 18.1 12 20.5c-2.3-2.4-3.5-5.3-3.5-8.5S9.7 5.9 12 3.5Z"/></svg>Country</dt><dd>${esc(countryOf(e))}</dd></div><div><dt><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 20V5a1 1 0 0 1 1-1h9a1 1 0 0 1 1 1v15"/><path d="M3.5 20h17"/><circle cx="13" cy="12.5" r=".8" fill="currentColor" stroke="none"/></svg>Doors</dt><dd>${esc(i.schedule[0][0])} ${tzOf(e)}</dd></div><div><dt><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>Showtime</dt><dd>${esc(e.time)} ${tzOf(e)}</dd></div><div class="gd-span2"><dt><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 20v-1a7 7 0 0 1 14 0v1"/></svg>Age</dt><dd>${esc(i.age)}</dd></div></dl><div class="gd-chips gd-chips-b"><span><b>Layout</b>${esc(layoutOf(e).label)}</span><span><b>Categories</b>${zonesOf(e).length}</span><span><b>Capacity</b>${venueCap(e).toLocaleString('en-GB')}</span></div><p class="gd-foot">Doors, stage times and the map are shown as the organizer published them.</p></section><section class="guide-block gd-card guide-faq"><header class="gd-head"><span class="gd-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"/><path d="M9.5 9.3a2.5 2.5 0 0 1 4.9.7c0 1.7-2.2 1.8-2.4 3.3"/><circle cx="12" cy="16.7" r=".6" fill="currentColor" stroke="none"/></svg></span><div><span class="eyebrow">GOOD TO KNOW</span><h2>Questions, answered.</h2></div></header><div class="faq-list">${faq.map(([q,ans,html],k)=>`<details class="faq"${k===0?' open':''}><summary>${esc(q)}<i class="faq-plus" aria-hidden="true"></i></summary><p>${html?ans:esc(ans)}</p></details>`).join('')}</div><p class="gd-foot gd-ask">Still unsure? Ask Rue, the assistant in the corner of the screen.</p></section></div>${rel.length?`<section class="guide-block guide-more"><span class="eyebrow">KEEP THE NIGHTS COMING</span><h2>You might also like</h2><div class="grid tgrid">${rel.map(card).join('')}</div></section>`:''}`}
function mainnetLaunch(){const net=networks.mainnet,live=/^0x[a-fA-F0-9]{40}$/.test(net.contractAddress||''),explorer=net.blockExplorerUrls?.[0]||'https://scan.botchain.ai';return `<section class="container page prose"><span class="eyebrow">TICKETRUE · MAINNET RELEASE</span><h1>${live?'Ticketrue is officially launched on BOT Chain Mainnet.':'Mainnet launch is being prepared.'}</h1>${live?`<p>Ticketrue’s ticket ownership and fair-resale contract is live on BOT Chain Mainnet. Concert tickets can be issued to wallets and verified publicly on the explorer.</p><p><strong>Contract:</strong> <a href="${esc(explorer)}/address/${esc(net.contractAddress)}" target="_blank" rel="noreferrer">${esc(net.contractAddress)}</a></p><p><strong>Network:</strong> BOT Chain Mainnet · Chain ID 677.</p><a class="btn" href="?network=mainnet#/discover">Open Ticketrue on Mainnet</a>`:`<p>Ticketrue is live and tested end-to-end on BOT Chain Testnet. The mainnet announcement will be published here only after its contract deployment is confirmed on the BOT Chain Explorer.</p><p class="notice">Status: waiting for mainnet BOT allocation and a signed MetaMask deployment transaction.</p><a class="btn" href="#/discover">Try the Testnet experience</a>`}</section>`}
function render(){clearInterval(timer);clearInterval(passTimer);clearInterval(liveTimer);clearInterval(aboutTimer);carousel?.dispose();carousel=null;heroTicket?.dispose();heroTicket=null;loginSceneVersion++;loginScene?.dispose();loginScene=null;machine?.dispose();machine=null;if(tour)endTour();shell();let p=path(),html='';if(['/profile','/organizer'].some(x=>p===x||p.startsWith(x+'/'))&&!user){returnTo=p;go('/login');return}if(p==='/')html=home();else if(p==='/discover')html=discover();else if(p==='/login'||p==='/signup')html=login(p==='/signup');else if(p==='/forgot')html='<section class="container page prose"><h1>Need a fresh start?</h1><p>Demo sign-in does not store passwords, so there is nothing to reset. Use sample details or the demo button to continue.</p><a class="btn" href="#/login">Back to login</a></section>';else if(p.startsWith('/event/'))html=detail(eventBy(p.split('/')[2]));else if(p==='/checkout')html=checkout();else if(p==='/tickets')html=ticketsPage();else if(p.startsWith('/tickets/'))html=ticketPage(p.split('/')[2]);else if(p.startsWith('/reveal/'))html=reveal(p.split('/')[2]);else if(p==='/machine')html=reveal(null,true);else if(p==='/profile')html=profile();else if(p==='/organizer')html=organizer();else if(p==='/resell')html=resell();else if(p.startsWith('/verify/'))html=verifyPage();else if(p==='/dashboard')html=dashboard();else if(p==='/gate')html=gate();else if(p==='/about')html=about();else if(p==='/launch')html=mainnetLaunch();else if(p==='/privacy'||p==='/terms')html=legal(p.slice(1));else html=missing();$('#main').innerHTML=html;enhanceSelects($('#main'));initMotion(p);document.title=(p==='/'?'Ticketrue — Concert Tickets, Verified On-Chain':(h1Text()||'Ticketrue')+' — Ticketrue');if(p==='/discover')carousel=mountCarousel($('#featured-carousel'));if(p==='/')heroTicket=mountHeroTicket($('#hero-home'));if(p==='/discover'&&(searchQuery||searchCountry||searchMode))filterEvents();if(p==='/discover'&&scrollToResults){scrollToResults=false;setTimeout(scrollToFilters,120)}if(p==='/login'||p==='/signup')loadLoginScene();if(p==='/checkout'){startCountdown();contextTour('checkout');if(payType==='bot')loadQuote()}if(p==='/'){loadLive();liveTimer=setInterval(loadLive,20000)}if(p.startsWith('/event/')){requestAnimationFrame(centreVenue);loadAvailability(eventBy(p.split('/')[2]));loadMarket(eventBy(p.split('/')[2]))}if(p==='/'||p==='/discover'||p.startsWith('/event/')||p==='/tickets')loadStocks();if(p==='/resell')loadResellPage();if(p.startsWith('/verify/'))loadVerify(decodeURIComponent(p.split('/')[2]));if(p==='/dashboard')loadDashboard();if(p==='/about'){tickAbout();aboutTimer=setInterval(tickAbout,1000)}if(p.startsWith('/tickets/')){const tk=ownTickets().find(x=>String(x.id)===p.split('/')[2]);if(tk){const g=orderGroup(tk);tkIndex=Math.max(0,g.findIndex(x=>x.id===tk.id));showTicket(tkIndex)}if(tk)for(const one of orderGroup(tk)){renderPass(one,null,'#pass-box-'+one.id);if(!one.demo)loadResaleBox(one)}}if(p.startsWith('/event/'))contextTour(!read('tour:event',false)?'event':'tier');if(p==='/tickets')contextTour('tickets');if(p.startsWith('/reveal/')||p==='/machine')loadMachine()}
document.addEventListener('input',e=>{if(e.target.id==='search'){searchQuery=e.target.value;filterEvents()}});document.addEventListener('change',e=>{if(e.target.id.endsWith('-filter'))filterEvents()});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='hero-search'){searchQuery=String(d.get('q')||'').trim();searchCountry=String(d.get('country')||'');scrollToResults=true;go('/discover');return}if(f.id==='gate-form'){gateLookup(String(d.get('id')||'').trim());return}if(f.hasAttribute('data-dash')){doDash(f,d);return}if(f.hasAttribute('data-demo-resale')){try{demoList(f.dataset.ticket,d.get('price'))}catch(err){toast(err.message)}return}if(f.hasAttribute('data-resale-form')){doResale(f.dataset.ticket,d.get('price'));return}if(f.id==='header-search-form'){searchQuery=String(d.get('q')||'').trim();$('.nav-shell')?.classList.remove('search-open');document.activeElement?.blur?.();if(path()==='/discover'){const input=$('#search');if(input){input.value=searchQuery;filterEvents()}requestAnimationFrame(scrollToFilters)}else{scrollToResults=true;go('/discover')}return}if(f.id==='login-form'){loginSuccess(String(d.get('name')||d.get('email').split('@')[0]),String(d.get('email')),d.has('remember'))}if(f.id==='event-form'){const id=f.dataset.id;const old=id?eventBy(id):null;const updated={...(old||{}),id:old?.id||Math.max(...events.map(x=>x.id))+1,slug:old?.slug||'concert-'+crypto.randomUUID().slice(0,8),title:name,artist:String(d.get('artist')),venue:String(d.get('venue')),city:String(d.get('city')),country:String(d.get('country')||'Indonesia'),date:String(d.get('date')),layout:String(d.get('layout')||'arena'),price:Number(d.get('price')),draft:d.has('draft'),genre:old?.genre||'Live Music',description:old?.description||'A new fictional live experience.',time:old?.time||'19:00',color:old?.color||'blue'};if(old)events=events.map(x=>x.id===old.id?updated:x);else events.push(updated);save('events',events);close();render();toast('Event saved on this device.')}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,[data-action]');if(!b)return;try{if(b.hasAttribute('data-close')){close();return}if(b.dataset.aboutMode){const mode=b.dataset.aboutMode;$$('[data-about-mode]').forEach(x=>{const selected=x.dataset.aboutMode===mode;x.classList.toggle('active',selected);x.setAttribute('aria-pressed',selected)});$('#about-choice').innerHTML=aboutChoice(mode);return}if(b.dataset.payType){payType=b.dataset.payType;render();return}if(b.dataset.payment){payment=b.dataset.payment;paymentRender();return}if(b.dataset.editEvent){eventForm(b.dataset.editEvent);return}if(b.dataset.verify){const t=tickets.find(t=>t.id===b.dataset.verify);const vr=$('#verify-result');if(t.demo){vr.textContent='Local demo record found. This is not an on-chain verification.';return}vr.textContent='Checking BOT Chain…';const ok=await web3.verifyTicket(t);vr.innerHTML=ok?`Ownership confirmed by the Ticketrue contract on BOT Chain. <a href="${chainConfig.blockExplorerUrls[0]}/address/${contractAddress}" target="_blank" rel="noreferrer">View contract</a>`:'Ownership could not be confirmed.';return}switch(b.dataset.action){case'carousel-next':carousel?.next();break;case'carousel-prev':carousel?.prev();break;case'toggle-search':{const shell=$('.nav-shell');const open=shell.classList.toggle('search-open');b.setAttribute('aria-expanded',String(open));if(open){shell.querySelector('.nav-links')?.classList.remove('open');shell.querySelector('.header-search input')?.focus()}break;}case'toggle-password':{const i=b.parentElement.querySelector('input');if(i){const show=i.type==='password';i.type=show?'text':'password';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',show?'Hide password':'Show password');b.classList.toggle('on',show);i.focus()}break}case'toggle-login-animation':if(loginScene){const paused=loginScene.toggle();b.textContent=paused?'Play animation':'Pause animation';b.setAttribute('aria-pressed',String(paused))}break;case'menu':$('.nav-shell')?.classList.remove('search-open');$('.nav-links').classList.toggle('open');b.setAttribute('aria-expanded',$('.nav-links').classList.contains('open'));break;case'how':$('#how').scrollIntoView({behavior:'smooth'});break;case'reset-filters':searchQuery='';searchCountry='';searchMode='';savedOnly=false;go('/discover');render();break;case'clear-local':dialog(`<div class="lg-confirm"><span class="lg-confirm-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4.5 7h15M9.5 7V4.5h5V7M6.5 7l1 13h9l1-13"/></svg></span><h2>Clear local data?</h2><p>This logs you out and removes everything Ticketrue saved in this browser: your demo tickets, saved concerts, organizer changes and tutorial progress. It can’t be undone.</p><div class="lg-confirm-actions"><button class="btn secondary" data-close>Keep my data</button><button class="lg-clear" data-action="clear-local-confirm">Yes, clear it</button></div></div>`);break;case'clear-local-confirm':{const clear=st=>{try{Object.keys(st).filter(k=>k.startsWith('tr2:')).forEach(k=>st.removeItem(k))}catch{}};clear(localStorage);clear(sessionStorage);try{web3.disconnect?.()}catch{}close();user=null;wallet='';order=null;paid=false;savedOnly=false;events=syncSeed(seed);tickets=[];saved=[];listings=seedListings();save('listings',listings);if(tour)endTour();location.hash='#/';render();toast('Local data cleared. You’re starting fresh.');break}case'toggle-saved':{savedOnly=!savedOnly;const t=$('.fsaved');if(t){t.classList.toggle('on',savedOnly);t.setAttribute('aria-pressed',String(savedOnly))}filterEvents();break}case'checkout':go('/checkout');break;case'demo-login':loginSuccess('Music Lover','demo@ticketrue.local',true);break;case'start-tour':startTour('global');break;case'skip-global':save('tour:global',true);close();break;case'tour-skip':endTour();break;case'tour-back':tour.index=Math.max(0,tour.index-1);drawTour();break;case'tour-next':if(++tour.index>=tours[tour.key].length){const key=tour.key;endTour();if(key==='event')contextTour('tier')}else drawTour();break;case'wallet':walletDialog();break;case'connect':b.disabled=true;try{await connectWallet();close()}catch(err){$('#wallet-error').textContent=err.message}finally{b.disabled=false}break;case'disconnect':wallet='';web3.disconnect();close();render();break;case'simulate':b.disabled=true;b.textContent='Confirming demo payment…';clearInterval(timer);await new Promise(r=>setTimeout(r,700));paid=true;if(path()==='/checkout')paymentRender();break;case'retry-payment':paymentRender();break;case'copy-va':await navigator.clipboard.writeText('DEMO-VA-0000-1234');toast('Demo reference copied.');break;case'issue-demo':await issueDemo();break;case'issue-real':await issueReal();break;case'issue-claim':await issueReal(true);break;case'demo-resale-buy':demoBuy(b.dataset.ticket);break;case'demo-resale-cancel':demoCancel(b.dataset.ticket);break;case'demo-sim-sale':demoSimSale(b.dataset.ticket);break;case'demo-resale-reset':listings=[...seedListings(),...listings.filter(l=>!l.tid.startsWith('DEMO-RS-'))];save('listings',listings);render();break;case'price-chip':{const f=b.closest('form');f.elements.price.value=Number(b.dataset.value).toLocaleString('en-US');updateReceive(f);break}case'scroll-to':document.getElementById(b.dataset.target)?.scrollIntoView({behavior:'smooth'});break;case'save':ev.preventDefault();ev.stopPropagation();toggleSaved(Number(b.dataset.event));break;case'wl-toggle':toggleWaitlist(Number(b.dataset.event));break;case'pass-sign':{const t=anyTicket(b.dataset.ticket);if(!t)throw Error('Ticket not found.');const s=await web3.signPass(t.id);await renderPass(t,s,'#pass-box-'+t.id);break}case'copy-link':await navigator.clipboard.writeText(b.dataset.link);toast('Link copied.');break;case'cal-add':addToCalendar(anyTicket(b.dataset.ticket));break;case'share-ticket':await shareTicket(anyTicket(b.dataset.ticket));break;case'dl-ticket':await downloadTicketPdf(anyTicket(b.dataset.ticket));break;case'tk-move':showTicket(tkIndex+(+b.dataset.delta));break;case'tk-go':showTicket(+b.dataset.i);break;case'dl-order':{const t=anyTicket(b.dataset.ticket);if(!t)break;const g=orderGroup(t);b.disabled=true;try{for(const one of g){await downloadTicketPdf(one);await new Promise(r=>setTimeout(r,450))}toast(`${g.length} e-tickets downloaded.`)}finally{b.disabled=false}break}case'dash-staff-remove':await web3.setStaffTx(b.dataset.addr,false,txStatus('#dash-state'));await loadDashboard();break;case'resale-cancel':await web3.cancelResale(b.dataset.ticket,txStatus('#resale-state-'+b.dataset.ticket));await loadResaleBox({id:b.dataset.ticket});break;case'resale-buy':{const id=b.dataset.ticket;await connectWallet();await web3.buyResale(id,BigInt(b.dataset.price),txStatus('#market-state'));await syncTickets();toast('The ticket is yours.');go('/tickets/'+id);break}case'gate-checkin':{const id=b.dataset.ticket,who=await connectWallet();if(!await web3.isGate(who))throw Error('This wallet is not gate staff. Connect the organizer or a staff wallet.');await web3.checkIn(id,txStatus('#gate-state'));toast('Ticket checked in.');if($('#verify-card'))await loadVerify(id);else await gateLookup(id);break}case'preview-machine':go('/machine');break;case'pick-zone':{const e=eventBy(b.dataset.event),id=b.dataset.zone;activeZone=activeZone===id?null:id;refreshSelector(e);if(activeZone)$('#cat-'+activeZone)?.scrollIntoView({block:'nearest',behavior:'smooth'});break}case'cat-qty':{const e=eventBy(b.dataset.event),id=b.dataset.zone;activeZone=id;const before=zoneQty(e,id);setZoneQty(e,id,before+(+b.dataset.delta));if(zoneQty(e,id)!==before){const o=$(`#cat-${id} output`);if(o){o.classList.add('bump',(+b.dataset.delta)>0?'b-up':'b-down')}const ln=$$('#cart-lines .cart-line').find(l=>l.dataset.zone===id);if(ln)ln.classList.add('flash')}break}case'replay-reveal':render();break;case'replay':go('/discover');setTimeout(()=>startTour('global'),150);break;case'reset-tours':Object.keys(tours).forEach(k=>save('tour:'+k,false));toast('All tutorials reset.');break;case'logout':user=null;wallet='';order=null;paid=false;returnTo='/discover';web3.disconnect();localStorage.removeItem('tr2:user');sessionStorage.removeItem('tr2:user');if(tour)endTour();close();if(path()==='/')render();else go('/');toast('You’re logged out.');break;case'new-event':eventForm();break;case'sync-tickets':b.disabled=true;await connectWallet();if(!contractAddress){toast('Contract is not configured. Local demo tickets are shown.');break}await syncTickets();render();break}}catch(err){toast(err.message||'Something went wrong. Try again.');if($('#transaction-state'))$('#transaction-state').innerHTML='<p class="notice error spacer">'+esc(err.message)+'</p>'}finally{if(b.isConnected)b.disabled=false}});
